const digits = (value: number | string) => new Intl.NumberFormat('fa-IR').format(Number(value));
const dateFa = (value: string) => new Intl.DateTimeFormat('fa-IR', { year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(value));
const fileSize = (bytes: number) => bytes ? `${(bytes / 1024 / 1024).toFixed(1)} مگابایت` : '—';
const tehranDay = (value: string | number | Date) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value));
const addedTimeFa = (value: string) => { const raw=Date.now()-new Date(value).getTime(),future=raw<0,diff=Math.abs(raw),suffix=future?'دیگر':'پیش',minutes=Math.floor(diff/60000),hours=Math.floor(diff/3600000),days=Math.floor(diff/86400000),count=(number:number)=>number===1?'یک':number===2?'دو':digits(number);if(minutes<1)return future?'تا لحظاتی دیگر':'همین حالا';if(minutes<60)return`${count(minutes)} دقیقه ${suffix}`;if(hours<24)return`${count(hours)} ساعت ${suffix}`;if(days<7)return`${count(days)} روز ${suffix}`;if(days<28){const weeks=Math.floor(days/7);return`${count(weeks)} هفته ${suffix}`;}if(days<360){const months=Math.max(1,Math.floor(days/30));return`${count(months)} ماه ${suffix}`;}const years=Math.max(1,Math.floor(days/365));return`${count(years)} سال ${suffix}`; };
const parseChapterInput = (value: string) => { const text=value.trim().replace(/[۰-۹]/g,char=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(char))),special=text.match(/^(\d+(?:\.\d+)?)\s*&\s*(\d+(?:\.\d+)?)$/);if(special){const left=Number(special[1]),right=Number(special[2]);return left>=0&&right>left?{display:`${special[1]}&${special[2]}`,sort:(left+right)/2,right}:null}const number=Number(text);return Number.isFinite(number)&&number>0?{display:text,sort:number,right:null as number|null}:null};

async function api<T>(url: string, options: RequestInit = {}, token?: string | null): Promise<T> {
  const headers = new Headers(options.headers);
  if (options.body && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
  if (token) headers.set('Authorization', `Bearer ${token}`);
  const response = await fetch(url, { ...options, headers });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || 'ارتباط با سرور ناموفق بود.');
  return data;
}

function trackRead(manhwaId: number, token?: string | null) {
  void api('/api/views', { method: 'POST', body: JSON.stringify({ manhwa_id: manhwaId }), keepalive: true }, token).catch(() => {});
  void api('/api/analytics', { method: 'POST', body: JSON.stringify({ event_type: 'manhwa_read', manhwa_id: manhwaId }), keepalive: true }, token).catch(() => {});
}

function uploadFileWithProgress(signedUrl: string, file: Blob, onProgress: (percent: number) => void) {
  return new Promise<void>((resolve, reject) => {
    const body = new FormData();
    body.append('cacheControl', '3600');
    body.append('', file, file instanceof File ? file.name : 'chunk.pdf');
    const xhr = new XMLHttpRequest();
    xhr.open('PUT', signedUrl);
    xhr.timeout = 10 * 60 * 1000;
    xhr.setRequestHeader('x-upsert', 'true');
    xhr.upload.onprogress = event => { if (event.lengthComputable) onProgress(Math.round(event.loaded / event.total * 100)); };
    xhr.onload = () => { if (xhr.status >= 200 && xhr.status < 300) resolve(); else { let detail='';try{detail=JSON.parse(xhr.responseText)?.message||JSON.parse(xhr.responseText)?.error||''}catch{}reject(new Error(detail||`خطای فضای ذخیره‌سازی با کد ${xhr.status}`)); } };
    xhr.onerror = () => reject(new Error('اتصال اینترنت هنگام آپلود قطع یا ناپایدار شد.'));
    xhr.ontimeout = () => reject(new Error('زمان آپلود این قطعه بیش از حد طول کشید.'));
    xhr.send(body);
  });
}

const waitForConnection = () => navigator.onLine ? Promise.resolve() : new Promise<void>(resolve => window.addEventListener('online', () => resolve(), { once: true }));

function useApiData<T>(url: string, initial: T) {
  const [data, setData] = useState<T>(initial);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const reload = useCallback(async () => {
    setLoading(true); setError('');
    try { setData(await api<T>(url)); } catch (e) { setError(e instanceof Error ? e.message : 'خطای ناشناخته'); }
    finally { setLoading(false); }
  }, [url]);
  useEffect(() => { reload(); }, [reload]);
  return { data, setData, loading, error, reload };
}

function ErrorBox({ message }: { message: string }) {
  if (!message) return null;
  return <div className="error-box" role="alert">{message}</div>;
}

