function AnalyticsChart({title,data}: {title:string;data:AnalyticsPoint[]}) {
  const width=920,height=250,padX=48,padY=34,max=Math.max(1,...data.map(point=>point.value)),step=data.length>1?(width-padX*2)/(data.length-1):0;
  const points=data.map((point,index)=>`${padX+index*step},${height-padY-(point.value/max)*(height-padY*2)}`).join(' ');
  return <section className="analytics-chart"><h3>{title}</h3><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={title}><line x1={padX} y1={padY} x2={padX} y2={height-padY}/><line x1={padX} y1={height-padY} x2={width-padX} y2={height-padY}/>{[0,.5,1].map(ratio=><g key={ratio}><line className="grid-line" x1={padX} y1={height-padY-ratio*(height-padY*2)} x2={width-padX} y2={height-padY-ratio*(height-padY*2)}/><text x={padX-10} y={height-padY-ratio*(height-padY*2)+4}>{digits(Math.round(max*ratio))}</text></g>)}<polyline points={points}/>{data.map((point,index)=><g key={`${point.label}-${index}`}><circle cx={padX+index*step} cy={height-padY-(point.value/max)*(height-padY*2)} r="4"><title>{`${point.label}: ${digits(point.value)}`}</title></circle>{(data.length<=12||index%2===0)&&<text className="x-label" x={padX+index*step} y={height-10}>{point.label}</text>}</g>)}</svg></section>;
}

