function ManhwaCard({ item, genres, showAddedTime=false }: { item: Manhwa; genres: Genre[]; showAddedTime?: boolean }) {
  const names = genres.filter(g => item.genre_ids?.includes(g.id)).slice(0,2);
  return <motion.article className="manhwa-card" whileHover={{ y: -7 }}>
    <Link to={`/manhwa/${item.slug}`} className="cover-wrap"><img src={item.cover_url} alt={`کاور ${item.title}`}/><span className="rating"><Star size={13} fill="currentColor"/> {Number(item.rating).toFixed(1)}</span><span className="status">{item.status}</span></Link>
    <div className="card-body"><Link to={`/manhwa/${item.slug}`}><h3>{item.title}</h3></Link><p>{item.author}</p>{showAddedTime&&<time className="added-time"><Clock3/> {addedTimeFa(item.created_at)}</time>}<div className="mini-tags">{names.map(g => <Link to={`/genres/${g.slug}`} key={g.id}>{g.name}</Link>)}</div></div>
  </motion.article>;
}

function HomePage() {
  const { user } = useAuth();
  const { data: manhwas, loading, error } = useApiData<Manhwa[]>('/api/manhwas', []);
  const { data: genres } = useApiData<Genre[]>('/api/genres', []);
  const { data: chapters, reload: reloadChapters } = useApiData<Chapter[]>('/api/chapters?latest=true', []);
  const { data: content } = useApiData<ContentRow[]>('/api/site-content', []);
  const { data: layoutRows } = useApiData<SiteLayoutRow[]>('/api/site-layout', []);
  const { data: viewStats, reload: reloadViewStats } = useApiData<ViewStats>('/api/views?public=true', {total:0,items:[]});
  const [slide, setSlide] = useState(0);
  const featured = [...manhwas].sort((a,b)=>(viewStats.items.find(v=>v.manhwa_id===b.id)?.views||0)-(viewStats.items.find(v=>v.manhwa_id===a.id)?.views||0)||b.rating-a.rating).slice(0,4);
  const c = Object.fromEntries(content.map(item => [item.content_key, item.value]));
  useEffect(() => { if (featured.length < 2) return; const id = setInterval(() => setSlide(v => (v + 1) % featured.length), 5500); return () => clearInterval(id); }, [featured.length]);
  useEffect(() => { const id = setInterval(reloadViewStats, 15000); return () => clearInterval(id); }, [reloadViewStats]);
  useEffect(() => { const id = setInterval(reloadChapters, 15000); return () => clearInterval(id); }, [reloadChapters]);
  const active = featured[slide] || manhwas[0];
  const manhwaById = (id: number) => manhwas.find(m => m.id === id);
  const newestManhwas = [...manhwas].sort((a,b)=>+new Date(b.created_at)-+new Date(a.created_at));
  const latestChapters = useMemo(() => { const seen = new Set<number>(); return [...chapters].sort((a,b)=>+new Date(b.created_at)-+new Date(a.created_at)).filter(ch => { if(seen.has(ch.manhwa_id)) return false; seen.add(ch.manhwa_id); return true; }); }, [chapters]);
  const layoutSections:Record<string,ReactNode>={
    newest:<section key="newest" className="section dark-panel"><div className="container"><div className="section-head"><div><span className="kicker">تازه به مانهوا هاب اضافه شده</span><h2>{c.recommended_heading||'جدیدترین مانهواها'}</h2></div><Link to="/manhwas">مشاهده همه <ArrowLeft/></Link></div><ErrorBox message={error}/>{loading?<LoadingCards/>:<div className="recommended-row">{newestManhwas.slice(0,15).map(m=><ManhwaCard key={m.id} item={m} genres={genres} showAddedTime/>)}</div>}</div></section>,
    updates:<section key="updates" className="section container updates-section"><div className="section-head"><div><span className="kicker">همین حالا منتشر شد</span><h2>{c.updates_heading||'آخرین آپدیت‌ها'}</h2></div><Link to="/latest">آرشیو آپدیت‌ها <ArrowLeft/></Link></div><div className="updates-list horizontal-updates">{latestChapters.map(ch=>{const m=manhwaById(ch.manhwa_id);if(!m)return null;return <Link to={`/reader/${ch.id}`} className="update-row" key={ch.id} onClick={()=>trackRead(ch.manhwa_id)}><img src={m.cover_url} alt=""/><div><h3>{m.title}</h3><p>چپتر جدید آپلود شد</p></div><span className="chapter-pill">چپتر {ch.display_number||digits(ch.chapter_number)} {ch.is_final&&<b className="end-badge">END</b>}</span><time>{dateFa(ch.created_at)}</time><ChevronLeft/></Link>})}</div></section>,
    cta:!user?<section key="cta" className="container cta-banner"><div><span className="eyebrow"><Library/> کتابخانه شخصی</span><h2>{c.cta_title||'داستان‌هایت را هیچ‌وقت گم نکن'}</h2><p>{c.cta_text||'حساب رایگان بساز، مانهواهای محبوبت را ذخیره کن و خواندن را از همان‌جایی که بودی ادامه بده.'}</p></div><Link className="light-btn" to="/login">ساخت حساب رایگان <ArrowLeft/></Link></section>:null,
  };
  const orderedSections=(layoutRows.length?layoutRows.map(row=>row.section_key):['newest','updates','cta']).filter(key=>layoutSections[key]!==undefined);

  return <>
    <section className="hero">
      <div className="hero-glow"/><div className="container hero-inner">
        {active ? <AnimatePresence mode="wait"><motion.div className="hero-content" key={active.id} initial={{opacity:0,x:30}} animate={{opacity:1,x:0}} exit={{opacity:0,x:-20}}>
          <span className="eyebrow"><Sparkles size={16}/>{c.hero_eyebrow || 'منتخب سردبیران مانهوا هاب'}</span>
          <h1>{c.hero_title || 'داستان بعدی تو'} <em>{active.title}</em></h1>
          <p>{active.summary}</p>
          <div className="hero-meta"><span><Star fill="currentColor"/> {active.rating}</span><span><Pencil/> {active.author}</span><span><Layers3/> {active.status}</span></div>
          <div className="hero-actions"><Link className="primary-btn large" to={`/manhwa/${active.slug}`}><Play fill="currentColor"/> شروع خواندن</Link><Link className="ghost-btn large" to="/manhwas">مشاهده آرشیو <ArrowLeft/></Link></div>
        </motion.div></AnimatePresence> : <div className="hero-content"><h1>مانهوا <em>هاب</em></h1><p>در حال آماده‌سازی کتابخانه...</p></div>}
        <div className="hero-visual">{active && <motion.img key={active.cover_url} initial={{opacity:0,scale:.96}} animate={{opacity:1,scale:1}} src={active.cover_url} alt={active.title}/>}<div className="floating-card"><span>امتیاز کاربران</span><strong>{active?.rating || '—'} <Star fill="currentColor"/></strong></div></div>
        <div className="slider-dots">{featured.map((m,i) => <button aria-label={`نمایش ${m.title}`} onClick={() => setSlide(i)} className={i===slide?'active':''} key={m.id}><img src={m.cover_url} alt=""/><span>{m.title}</span></button>)}</div>
      </div>
    </section>

    {orderedSections.map(key=>layoutSections[key])}
  </>;
}

