function GenreDetailPage() {
  const { slug } = useParams();
  const { data: genres, loading } = useApiData<Genre[]>('/api/genres', []);
  const { data: manhwas } = useApiData<Manhwa[]>('/api/manhwas', []);
  const genre = genres.find(g => g.slug === slug);
  if (!loading && !genre) return <NotFound/>;
  const items = genre ? manhwas.filter(m => m.genre_ids?.includes(genre.id)) : [];
  return <PageHero eyebrow="آرشیو ژانر" title={genre?.name || 'در حال بارگذاری'} text={genre?.description || ''} icon={<Sparkles/>}>
    {loading ? <LoadingCards/> : items.length ? <div className="card-grid">{items.map(m => <ManhwaCard key={m.id} item={m} genres={genres}/>)}</div> : <Empty icon={<BookOpen/>} title="هنوز عنوانی ثبت نشده" text="به‌زودی مانهواهای تازه‌ای به این ژانر اضافه می‌شود."/>}
  </PageHero>;
}

function ManhwasPage({ latest = false }: { latest?: boolean }) {
  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const [query, setQuery] = useState(params.get('q') || '');
  const [author, setAuthor] = useState('');
  const [genreId, setGenreId] = useState('');
  const { data: manhwas, loading, error } = useApiData<Manhwa[]>('/api/manhwas', []);
  const { data: genres } = useApiData<Genre[]>('/api/genres', []);
  const filtered = useMemo(() => manhwas.filter(m => (!query || m.title.toLowerCase().includes(query.toLowerCase()) || m.english_title?.toLowerCase().includes(query.toLowerCase())) && (!author || m.author.includes(author)) && (!genreId || m.genre_ids?.includes(Number(genreId)))).sort((a,b) => latest ? +new Date(b.updated_at)-+new Date(a.updated_at) : b.rating-a.rating), [manhwas, query, author, genreId, latest]);
  return <PageHero eyebrow={latest ? 'تازه از راه رسیده' : 'کتابخانه مانهوا هاب'} title={latest ? 'آخرین آپدیت‌ها' : 'همه مانهواها'} text="عنوان بعدی خودت را با جستجوی دقیق پیدا کن." icon={latest ? <Clock3/> : <BookOpen/>}>
    <div className="filter-bar"><label><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="جستجوی عنوان..."/></label><label><Pencil/><input value={author} onChange={e=>setAuthor(e.target.value)} placeholder="نام نویسنده..."/></label><label><Filter/><select value={genreId} onChange={e=>setGenreId(e.target.value)}><option value="">همه ژانرها</option>{genres.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></label><button className="ghost-btn" onClick={()=>{setQuery('');setAuthor('');setGenreId('')}}><X/> پاک‌کردن</button></div>
    <div className="results-head"><strong>{digits(filtered.length)} نتیجه</strong><span>مرتب‌سازی: {latest ? 'جدیدترین بروزرسانی' : 'بالاترین امتیاز'}</span></div><ErrorBox message={error}/>{loading?<LoadingCards/>:<div className="card-grid">{filtered.map(m=><ManhwaCard key={m.id} item={m} genres={genres}/>)}</div>}
  </PageHero>;
}

function ManhwaDetailPage() {
  const { slug } = useParams();
  const { session, user, isAdmin } = useAuth();
  const { data: manhwas, loading } = useApiData<Manhwa[]>('/api/manhwas', []);
  const { data: genres } = useApiData<Genre[]>('/api/genres', []);
  const item = manhwas.find(m=>m.slug===slug);
  const { data: chapters } = useApiData<Chapter[]>(item ? `/api/chapters?manhwa_id=${item.id}` : '/api/chapters?manhwa_id=-1', []);
  const { data: comments, reload: reloadComments } = useApiData<Comment[]>(item ? `/api/comments?manhwa_id=${item.id}` : '/api/comments?manhwa_id=-1', []);
  const { data: replies, reload: reloadReplies } = useApiData<CommentReply[]>(item ? `/api/replies?manhwa_id=${item.id}` : '/api/replies?manhwa_id=-1', []);
  const { data: pins, reload: reloadPins } = useApiData<PinnedComment[]>('/api/pins', []);
  const avatarIds=[...new Set([user?.id,...comments.map(c=>c.user_id),...replies.map(r=>r.user_id)].filter(Boolean))] as string[];
  const { data: commentAvatars } = useApiData<UserAvatar[]>(`/api/avatar?ids=${encodeURIComponent(avatarIds.length?avatarIds.join(','):'none')}`, []);
  const { data: credits } = useApiData<ManhwaCredit[]>(item ? `/api/manhwa-credits?manhwa_id=${item.id}` : '/api/manhwa-credits?manhwa_id=-1', []);
  const [comment, setComment] = useState('');
  const [replyTo, setReplyTo] = useState<number|null>(null);
  const [replyBody, setReplyBody] = useState('');
  const [editTarget, setEditTarget] = useState<{kind:'comment'|'reply';id:number;body:string}|null>(null);
  const [message, setMessage] = useState('');
  const [readChapterIds, setReadChapterIds] = useState<number[]>([]);
  const [downloadingChapter, setDownloadingChapter] = useState<number|null>(null);
  useEffect(()=>{if(item?.id)void api('/api/analytics',{method:'POST',body:JSON.stringify({event_type:'manhwa_view',manhwa_id:item.id}),keepalive:true},session?.access_token).catch(()=>{});},[item?.id,session?.access_token]);
  useEffect(()=>{if(!user||!item?.id||!session?.access_token){setReadChapterIds([]);return;}api<ChapterRead[]>(`/api/chapter-reads?manhwa_id=${item.id}`,{},session.access_token).then(rows=>setReadChapterIds(rows.map(row=>row.chapter_id))).catch(()=>setReadChapterIds([]));},[user?.id,item?.id,session?.access_token]);
  if (!loading && !item) return <NotFound/>;
  if (!item) return <div className="page-loading"><LoaderCircle className="spin"/> در حال دریافت...</div>;
  const itemGenres=genres.filter(g=>item.genre_ids?.includes(g.id));
  const writer=credits[0]?.writer||'ثبت نشده';
  const ownCommentCount=comments.filter(c=>c.user_id===user?.id).length;
  const pinnedCommentIds=new Set(pins.map(pin=>pin.comment_id));
  const avatarFor=(userId?:string)=>commentAvatars.find(avatar=>avatar.id===userId)?.url;
  const downloadChapter=async(chapter:Chapter)=>{if(!user||!session?.access_token){setMessage('برای دانلود چپتر ابتدا وارد حساب شوید.');return;}setDownloadingChapter(chapter.id);setMessage('');try{const{url}=await api<{url:string}>('/api/download',{method:'POST',body:JSON.stringify({chapter_id:chapter.id})},session.access_token);const link=document.createElement('a');link.href=url;link.rel='noopener';document.body.appendChild(link);link.click();link.remove();}catch(e){setMessage(e instanceof Error?e.message:'دانلود چپتر ناموفق بود.')}finally{setDownloadingChapter(null)}};
  const addShelf=async(shelf:string)=>{ if(!user){setMessage('برای افزودن به کتابخانه وارد شوید.');return;} try{await api('/api/library',{method:'POST',body:JSON.stringify({manhwa_id:item.id,shelf})},session?.access_token);setMessage('در کتابخانه شما ذخیره شد.');}catch(e){setMessage(e instanceof Error?e.message:'خطا');}};
  const submitComment=async(e:FormEvent)=>{e.preventDefault();if(comment.trim().length<3){setMessage('متن دیدگاه باید حداقل ۳ حرف باشد.');return;}try{await api('/api/comments',{method:'POST',body:JSON.stringify({manhwa_id:item.id,body:comment})},session?.access_token);setComment('');setMessage('دیدگاه شما ثبت شد.');reloadComments();}catch(err){setMessage(err instanceof Error?err.message:'خطا');}};
  const submitReply=async(e:FormEvent)=>{e.preventDefault();if(!replyTo||replyBody.trim().length<2){setMessage('متن پاسخ باید حداقل ۲ حرف باشد.');return;}try{await api('/api/replies',{method:'POST',body:JSON.stringify({comment_id:replyTo,body:replyBody})},session?.access_token);setReplyBody('');setReplyTo(null);setMessage('پاسخ شما ثبت شد.');reloadReplies();}catch(err){setMessage(err instanceof Error?err.message:'خطا');}};
  const submitEdit=async(e:FormEvent)=>{e.preventDefault();if(!editTarget)return;const minimum=editTarget.kind==='comment'?3:2;if(editTarget.body.trim().length<minimum){setMessage(`متن باید حداقل ${digits(minimum)} حرف باشد.`);return;}try{await api(editTarget.kind==='comment'?'/api/comments':'/api/replies',{method:'PUT',body:JSON.stringify({id:editTarget.id,body:editTarget.body})},session?.access_token);setEditTarget(null);setMessage('ویرایش با موفقیت ذخیره شد.');editTarget.kind==='comment'?reloadComments():reloadReplies();}catch(err){setMessage(err instanceof Error?err.message:'خطا');}};
  const togglePublicPin=async(commentId:number)=>{const pinned=pinnedCommentIds.has(commentId);try{await api('/api/pins',{method:pinned?'DELETE':'POST',body:JSON.stringify({comment_id:commentId})},session?.access_token);reloadPins();setMessage(pinned?'کامنت از سنجاق خارج شد.':'کامنت سنجاق شد.');}catch(err){setMessage(err instanceof Error?err.message:'خطا');}};
  const editableBody=(kind:'comment'|'reply',id:number,body:string,owned:boolean)=>editTarget?.kind===kind&&editTarget.id===id?<form className="inline-edit-form" onSubmit={submitEdit}><textarea autoFocus value={editTarget.body} onChange={e=>setEditTarget({...editTarget,body:e.target.value})} maxLength={700}/><button className="primary-btn">ذخیره</button><button type="button" className="ghost-btn" onClick={()=>setEditTarget(null)}>انصراف</button></form>:<><p>{body}</p>{owned&&<button className="edit-comment-btn" onClick={()=>setEditTarget({kind,id,body})}><Pencil/> ویرایش</button>}</>;
  return <>
    <section className="detail-hero"><div className="detail-bg" style={{backgroundImage:`url(${item.cover_url})`}}/><div className="container detail-grid"><img className="detail-cover" src={item.cover_url} alt={item.title}/><div className="detail-copy"><span className="eyebrow"><Sparkles/> مانهوا منتخب</span><h1>{item.title}</h1>{item.english_title&&<h2 className="english-title" dir="ltr">{item.english_title}</h2>}<p>{item.summary}</p><div className="detail-tags">{itemGenres.map(g=><Link to={`/genres/${g.slug}`} key={g.id}>{g.name}</Link>)}</div><div className="detail-stats"><span><Star fill="currentColor"/><b>{item.rating}</b><small>امتیاز</small></span><span><Pencil/><b>{writer}</b><small>نویسنده</small></span><span><Layers3/><b>{digits(chapters.length)}</b><small>چپتر</small></span></div><div className="hero-actions">{chapters[0]&&<Link className="primary-btn large" to={`/reader/${chapters[chapters.length-1].id}`} onClick={()=>trackRead(item.id,session?.access_token)}><BookOpen/> شروع خواندن</Link>}<button className="ghost-btn large" onClick={()=>addShelf('favorite')}><Heart/> علاقه‌مندی</button><button className="ghost-btn large" onClick={()=>addShelf('library')}><Bookmark/> کتابخانه</button></div>{message&&<p className="inline-message">{message}</p>}</div></div></section>
    <section className="container detail-content"><div className="chapters-panel"><div className="panel-title"><h2>چپترها</h2><span>{digits(chapters.length)} چپتر منتشرشده</span></div>{chapters.length?chapters.map(ch=>{const isRead=readChapterIds.includes(ch.id),isSpecial=Boolean(ch.display_number?.includes('&'));return <div className="chapter-row" key={ch.id}><span className={isSpecial?'chapter-number special':'chapter-number'}>{ch.display_number||digits(ch.chapter_number)}</span><Link className="chapter-info" to={`/reader/${ch.id}`} onClick={()=>trackRead(item.id,session?.access_token)}><strong>{ch.title.replace(/فصل/g,'چپتر')}</strong><small>{dateFa(ch.created_at)}</small></Link><div className="chapter-labels">{ch.is_final&&<span className="end-badge">END</span>}{user&&<span className={isRead?'read-status read':'read-status new'}>{isRead?'خوانده شده':'جدید'}</span>}<span className="quality">{ch.quality}</span></div><div className="chapter-actions"><Link to={`/reader/${ch.id}`} onClick={()=>trackRead(item.id,session?.access_token)} aria-label="خواندن چپتر"><BookOpen/></Link>{user?<button onClick={()=>downloadChapter(ch)} disabled={downloadingChapter===ch.id} aria-label="دانلود چپتر">{downloadingChapter===ch.id?<LoaderCircle className="spin"/>:<Download/>}<span>دانلود</span></button>:<Link to="/login" className="locked-download" title="برای دانلود وارد شوید"><LockKeyhole/><span>ورود برای دانلود</span></Link>}</div></div>}):<Empty icon={<FileText/>} title="چپتری منتشر نشده" text="اولین چپتر به‌زودی منتشر می‌شود."/>}</div>
      <aside className="info-panel"><h3>اطلاعات اثر</h3><dl><div><dt>نام انگلیسی</dt><dd dir="ltr">{item.english_title||'—'}</dd></div><div><dt>وضعیت</dt><dd>{item.status}</dd></div><div><dt>نویسنده</dt><dd>{writer}</dd></div><div><dt>مترجمان</dt><dd>{item.author}</dd></div><div><dt>امتیاز</dt><dd>{item.rating} از ۱۰</dd></div><div><dt>آخرین بروزرسانی</dt><dd>{dateFa(item.updated_at)}</dd></div></dl></aside>
    </section>
    <section className="container comments-section"><div className="panel-title"><h2>دیدگاه خوانندگان</h2><span>{digits(comments.length)} دیدگاه</span></div>{user?(ownCommentCount<5?<form className="comment-form" onSubmit={submitComment}><div className="avatar comment-form-avatar">{avatarFor(user.id)?<img src={avatarFor(user.id)} alt=""/>:(displayName=>displayName?.[0]||'ک')(user.user_metadata?.display_name)}</div><textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="نظرت درباره این مانهوا چیست؟" maxLength={700}/><button className="primary-btn"><Send/> ارسال</button></form>:<div className="login-note"><MessageCircle/><span>سقف ۵ کامنت شما برای این مانهوا تکمیل شده است.</span></div>):<div className="login-note"><LockKeyhole/><span>برای ثبت دیدگاه، ابتدا وارد حساب خود شوید.</span><Link to="/login">ورود</Link></div>}{message&&<p className="inline-message">{message}</p>}<div className="comments-list">{[...comments].sort((a,b)=>Number(pinnedCommentIds.has(b.id))-Number(pinnedCommentIds.has(a.id))).map(c=>{const thread=replies.filter(r=>r.comment_id===c.id);const hasReplied=thread.some(r=>r.user_id===user?.id);const commentAvatar=avatarFor(c.user_id),isPinned=pinnedCommentIds.has(c.id);return <article className={isPinned?'pinned-comment':''} key={c.id}><div className="avatar">{commentAvatar?<img src={commentAvatar} alt={`پروفایل ${c.display_name}`}/>:c.display_name?.[0]||'ک'}</div><div className="comment-content"><CommentName comment={c}/>{isPinned&&<span className="pinned-badge">سنجاق‌شده</span>}<time>{dateFa(c.created_at)}</time>{editableBody('comment',c.id,c.body,c.user_id===user?.id)}<div className="comment-actions"><button disabled={thread.length>=200||hasReplied} onClick={()=>{if(!user){setMessage('برای پاسخ دادن وارد حساب شوید.');return;}setReplyTo(replyTo===c.id?null:c.id);setReplyBody('')}}><MessageCircle/> {hasReplied?'پاسخ داده‌اید':'پاسخ'} <span>{digits(thread.length)}</span></button>{isAdmin&&<button onClick={()=>togglePublicPin(c.id)}><Bookmark fill={isPinned?'currentColor':'none'}/> {isPinned?'برداشتن سنجاق':'سنجاق'}</button>}<small>{digits(thread.length)} از ۲۰۰ پاسخ</small></div>{thread.length>0&&<div className="reply-list">{thread.map(reply=>{const replyAvatar=avatarFor(reply.user_id);return <div className="reply-item" key={reply.id}><div className="avatar">{replyAvatar?<img src={replyAvatar} alt={`پروفایل ${reply.display_name}`}/>:reply.display_name?.[0]||'ک'}</div><div><ReplyName reply={reply}/><time>{dateFa(reply.created_at)}</time>{editableBody('reply',reply.id,reply.body,reply.user_id===user?.id)}</div></div>})}</div>}{replyTo===c.id&&user&&!hasReplied&&thread.length<200&&<form className="reply-form" onSubmit={submitReply}><textarea autoFocus value={replyBody} onChange={e=>setReplyBody(e.target.value)} placeholder={`پاسخ به ${c.display_name}...`} maxLength={700}/><button className="primary-btn"><Send/> ارسال پاسخ</button><button type="button" className="ghost-btn" onClick={()=>setReplyTo(null)}>انصراف</button></form>}</div></article>})}</div></section>
  </>;
}

function ReaderPage() {
  const { id } = useParams();
  const { user, session } = useAuth();
  const { data: chapters, loading } = useApiData<Chapter[]>(`/api/chapters?id=${id}`, []);
  const chapter=chapters[0];
  const documentRef=useRef<HTMLDivElement>(null);
  const [rendering,setRendering]=useState(true);
  const [progress,setProgress]=useState(0);
  const [renderError,setRenderError]=useState('');
  const [retry,setRetry]=useState(0);
  useEffect(()=>{
    if(!chapter?.pdf_url||!documentRef.current)return;
    let cancelled=false,task:ReturnType<typeof getDocument>|null=null;
    const host=documentRef.current;
    host.innerHTML='';setRendering(true);setRenderError('');setProgress(0);
    (async()=>{try{
      if(chapter.chunk_urls&&chapter.chunk_urls.length>1){
        const buffers=await Promise.all(chapter.chunk_urls.map(url=>fetch(url).then(response=>{if(!response.ok)throw new Error('chunk');return response.arrayBuffer()})));
        const total=buffers.reduce((sum,buffer)=>sum+buffer.byteLength,0),merged=new Uint8Array(total);let offset=0;
        buffers.forEach(buffer=>{merged.set(new Uint8Array(buffer),offset);offset+=buffer.byteLength});
        task=getDocument({data:merged});
      }else task=getDocument({url:chapter.pdf_url,rangeChunkSize:262144,disableAutoFetch:false,disableStream:false});
      const pdf=await task.promise;
      if(user&&session?.access_token)await api('/api/chapter-reads',{method:'POST',body:JSON.stringify({chapter_id:chapter.id})},session.access_token).catch(()=>{});
      for(let pageNumber=1;pageNumber<=pdf.numPages;pageNumber++){
        if(cancelled)return;
        const page=await pdf.getPage(pageNumber);
        const base=page.getViewport({scale:1});
        const cssScale=Math.min(1.6,Math.max(.55,Math.min(window.innerWidth-24,1000)/base.width));
        const pixelRatio=Math.min(window.devicePixelRatio||1,2);
        const viewport=page.getViewport({scale:cssScale*pixelRatio});
        const canvas=document.createElement('canvas');
        canvas.width=viewport.width;canvas.height=viewport.height;
        canvas.style.width=`${viewport.width/pixelRatio}px`;canvas.style.height=`${viewport.height/pixelRatio}px`;
        await page.render({canvas,canvasContext:canvas.getContext('2d')!,viewport}).promise;
        if(!cancelled)host.appendChild(canvas);
        setProgress(Math.round(pageNumber/pdf.numPages*100));
      }
    }catch{if(!cancelled)setRenderError('بارگذاری صفحات PDF ناموفق بود.');}finally{if(!cancelled)setRendering(false);}})();
    return()=>{cancelled=true;if(task)void task.destroy();};
  },[chapter?.pdf_url,chapter?.id,chapter?.chunk_urls,retry,user?.id,session?.access_token]);
  if(loading)return <div className="page-loading"><LoaderCircle className="spin"/> در حال آماده‌سازی PDF...</div>;
  if(!chapter)return <NotFound/>;
  return <div className="secure-reader" onContextMenu={e=>e.preventDefault()}><header className="secure-reader-head"><Link to="/manhwas"><ArrowLeft/> بازگشت</Link><div><strong>{chapter.title.replace(/فصل/g,'چپتر')}</strong><small>چپتر {chapter.display_number||digits(chapter.chapter_number)} · حالت فقط مطالعه</small></div><span>{rendering?`${digits(progress)}٪`:'آماده'}</span></header>{rendering&&progress===0&&<div className="reader-loading"><LoaderCircle className="spin"/> در حال دریافت PDF...</div>}{renderError&&<div className="reader-error"><FileText/><p>{renderError}</p><button className="primary-btn" onClick={()=>setRetry(v=>v+1)}>تلاش دوباره</button></div>}<div className="reader-document" ref={documentRef}/></div>;
}

function LoginPage({ admin = false }: { admin?: boolean }) {
  const { user, isAdmin }=useAuth(); const navigate=useNavigate(); const [signup,setSignup]=useState(false); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [name,setName]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); const [emailSent,setEmailSent]=useState(false);
  useEffect(()=>{if(user)navigate(isAdmin?'/admin':'/profile');},[user,isAdmin,navigate]);
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');setBusy(true);try{
    if(admin){
      const {error:otpError}=await supabase.auth.signInWithOtp({email:email.trim(),options:{emailRedirectTo:`${window.location.origin}/#/admin`,shouldCreateUser:false}});
      if(otpError)throw otpError;setEmailSent(true);return;
    }
    if(password.length<6)throw new Error('رمز عبور باید حداقل ۶ کاراکتر باشد.');
    const result=signup?await supabase.auth.signUp({email:email.trim(),password,options:{data:{display_name:name}}}):await supabase.auth.signInWithPassword({email:email.trim(),password});
    if(result.error)throw result.error;if(result.data.session){await api('/api/users',{method:'POST',body:JSON.stringify({display_name:name})},result.data.session.access_token);}navigate('/profile');
  }catch(err){setError(err instanceof Error?err.message:'ورود ناموفق بود.');}finally{setBusy(false);}};
  return <div className="auth-page"><div className="auth-art"><Logo/><div><span className="eyebrow"><Sparkles/> {admin?'ناحیه امن مدیریت':'به جمع داستان‌خوان‌ها خوش آمدی'}</span><h1>{admin?'کنترل کامل، در یک نگاه':'هر داستان، یک جهان تازه'}</h1><p>{admin?'دسترسی کامل به مدیریت مانهواها، کاربران و کامنت‌ها با ورود امن ایمیلی.':'کتابخانه‌ات را بساز، پیشرفت خواندن را نگه‌دار و هیچ چپتر تازه‌ای را از دست نده.'}</p></div><small>مانهوا هاب · تجربه خواندن نسل جدید</small></div><div className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-title"><span className="round-icon">{admin?<ShieldCheck/>:<UserRound/>}</span><h2>{admin?'ورود مدیر':signup?'ساخت حساب':'ورود به حساب'}</h2><p>{admin?'لینک ورود امن به ایمیل ادمین ارسال می‌شود.':'با ایمیل خود ادامه دهید.'}</p></div><ErrorBox message={error}/>{emailSent&&<p className="inline-message">لینک ورود ارسال شد؛ صندوق ایمیل خود را بررسی کنید.</p>}{signup&&!admin&&<label>نام نمایشی<input required value={name} onChange={e=>setName(e.target.value)} placeholder="مثلاً آریا"/></label>}<label>{admin?'ایمیل ادمین':'ایمیل'}<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label>{!admin&&<label>رمز عبور<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="حداقل ۶ کاراکتر"/></label>}<button className="primary-btn full" disabled={busy||emailSent}>{busy?<LoaderCircle className="spin"/>:admin?<Send/>:<LogIn/>}{busy?'لطفاً صبر کنید...':admin?emailSent?'لینک ارسال شد':'ارسال لینک ورود':signup?'ثبت‌نام':'ورود'}</button>{!admin&&<><div className="divider"><span>یا</span></div><button type="button" className="google-btn" onClick={()=>{try{signInWithGoogle('مانهوا هاب')}catch(e){setError(e instanceof Error?e.message:'خطا')}}}><b>G</b> ادامه با Google</button><p className="switch-auth">{signup?'حساب داری؟':'هنوز عضو نیستی؟'} <button type="button" onClick={()=>setSignup(v=>!v)}>{signup?'وارد شو':'رایگان ثبت‌نام کن'}</button></p></>}</form></div></div>;
}

function Protected({ children, admin=false }: { children: ReactNode; admin?: boolean }) {const {user,isAdmin,loading}=useAuth();if(loading)return <div className="page-loading"><LoaderCircle className="spin"/></div>;if(!user)return <Navigate to={admin?'/admin-login':'/login'} replace/>;if(admin&&!isAdmin)return <Navigate to="/" replace/>;return children;}

function ProfilePage(){const {user,session}=useAuth();const [rows,setRows]=useState<LibraryRow[]>([]);const [manhwas,setManhwas]=useState<Manhwa[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [tab,setTab]=useState('library');const [displayName,setDisplayName]=useState(user?.user_metadata?.display_name||user?.email?.split('@')[0]||'');const [editingName,setEditingName]=useState(false);const [savingName,setSavingName]=useState(false);const [nameMessage,setNameMessage]=useState('');const [avatarUrl,setAvatarUrl]=useState(user?.user_metadata?.avatar_url||'');const [avatarBusy,setAvatarBusy]=useState(false);const [avatarMessage,setAvatarMessage]=useState('');const avatarInput=useRef<HTMLInputElement>(null);
  const reload=useCallback(async()=>{setLoading(true);try{const [r,m,a]=await Promise.all([api<LibraryRow[]>('/api/library',{},session?.access_token),api<Manhwa[]>('/api/manhwas'),api<UserAvatar|null>('/api/avatar',{},session?.access_token)]);setRows(r);setManhwas(m);if(a?.url)setAvatarUrl(a.url);}catch(e){setError(e instanceof Error?e.message:'خطا');}finally{setLoading(false)}},[session?.access_token]);useEffect(()=>{reload()},[reload]);
  const remove=async(id:number)=>{try{await api('/api/library',{method:'DELETE',body:JSON.stringify({id})},session?.access_token);reload()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
  const saveDisplayName=async(e:FormEvent)=>{e.preventDefault();const next=displayName.trim();setNameMessage('');if(next.length<2||next.length>40){setNameMessage('نام نمایشی باید بین ۲ تا ۴۰ کاراکتر باشد.');return;}setSavingName(true);try{const{error:updateError}=await supabase.auth.updateUser({data:{display_name:next}});if(updateError)throw updateError;await api('/api/users',{method:'POST',body:JSON.stringify({display_name:next})},session?.access_token);setEditingName(false);setNameMessage('نام نمایشی ذخیره شد.');}catch(e){setNameMessage(e instanceof Error?e.message:'ویرایش نام ناموفق بود.')}finally{setSavingName(false)}};
  const uploadAvatar=async(file?:File)=>{if(!file)return;setAvatarMessage('');if(!['image/jpeg','image/png'].includes(file.type)){setAvatarMessage('فقط فایل JPG یا PNG مجاز است.');return;}if(file.size>5*1024*1024){setAvatarMessage('حجم تصویر باید حداکثر ۵ مگابایت باشد.');return;}setAvatarBusy(true);try{const signed=await api<{path:string;token:string}>('/api/avatar',{method:'POST',body:JSON.stringify({action:'sign',fileSize:file.size,contentType:file.type})},session?.access_token);const{error:uploadError}=await supabase.storage.from('profile-images').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type});if(uploadError)throw uploadError;const saved=await api<UserAvatar>('/api/avatar',{method:'POST',body:JSON.stringify({action:'finalize',path:signed.path,contentType:file.type})},session?.access_token);setAvatarUrl(saved.url);await supabase.auth.updateUser({data:{avatar_url:saved.url}});setAvatarMessage('عکس پروفایل ذخیره شد.');if(avatarInput.current)avatarInput.current.value='';}catch(e){setAvatarMessage(e instanceof Error?e.message:'آپلود تصویر ناموفق بود.')}finally{setAvatarBusy(false)}};
  const logout=async()=>{await supabase.auth.signOut()};const tabs=[['profile','پروفایل',CircleUserRound],['library','کتابخانه',Library],['reading','در حال خواندن',BookOpen],['favorite','علاقه‌مندی‌ها',Heart],['history','تاریخچه',History]] as const;const shown=tab==='library'?rows:rows.filter(r=>r.shelf===tab);
  const profileSettings=<div className="profile-settings-panel"><div className="profile-settings-avatar">{avatarUrl?<img src={avatarUrl} alt={`عکس پروفایل ${displayName}`}/>:<span>{(user?.email||'م')[0].toUpperCase()}</span>}</div><div><h3>عکس پروفایل</h3><p>یک تصویر JPG یا PNG با حداکثر حجم ۵ مگابایت انتخاب کنید.</p><input ref={avatarInput} hidden type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png" onChange={e=>uploadAvatar(e.target.files?.[0])}/><button className="avatar-upload-btn" disabled={avatarBusy} onClick={()=>avatarInput.current?.click()}><UploadCloud/> {avatarBusy?'در حال آپلود...':'انتخاب عکس پروفایل'}</button>{avatarMessage&&<em className="name-message">{avatarMessage}</em>}</div><div className="profile-name-settings"><h3>نام نمایشی</h3><p>این نام کنار کامنت‌ها و پاسخ‌های شما نمایش داده می‌شود.</p>{editingName?<form className="display-name-form" onSubmit={saveDisplayName}><input autoFocus value={displayName} onChange={e=>setDisplayName(e.target.value)} maxLength={40}/><div><button className="primary-btn" disabled={savingName}>{savingName?'در حال ذخیره...':'ذخیره'}</button><button type="button" className="ghost-btn" onClick={()=>setEditingName(false)}>انصراف</button></div></form>:<><strong>{displayName}</strong><button className="edit-name-btn" onClick={()=>setEditingName(true)}><Pencil/> ویرایش نام نمایشی</button></>}{nameMessage&&<em className="name-message">{nameMessage}</em>}</div></div>;
  return <PageHero eyebrow="فضای شخصی شما" title={`سلام، ${displayName||'کتاب‌خوان'}`} text="مانهواها و پیشرفت خواندن خود را از اینجا مدیریت کنید." icon={<CircleUserRound/>}><div className="profile-layout"><aside className="profile-sidebar"><div className="profile-person"><div className="profile-avatar">{avatarUrl?<img src={avatarUrl} alt={`عکس پروفایل ${displayName}`}/>:<span>{(user?.email||'م')[0].toUpperCase()}</span>}</div><strong>{displayName||'کاربر مانهوا هاب'}</strong><small>{user?.email}</small></div>{tabs.map(([key,label,Icon])=><button className={tab===key?'active':''} onClick={()=>setTab(key)} key={key}><Icon/>{label}{key!=='profile'&&<span>{digits(key==='library'?rows.length:rows.filter(r=>r.shelf===key).length)}</span>}</button>)}<button className="logout" onClick={logout}><LogOut/> خروج</button></aside><section className="profile-content"><div className="panel-title"><h2>{tabs.find(t=>t[0]===tab)?.[1]}</h2>{tab!=='profile'&&<span>{digits(shown.length)} عنوان</span>}</div><ErrorBox message={error}/>{tab==='profile'?profileSettings:loading?<LoadingCards/>:shown.length?<div className="library-list">{shown.map(row=>{const m=manhwas.find(x=>x.id===row.manhwa_id);if(!m)return null;return <article key={row.id}><img src={m.cover_url} alt=""/><div><Link to={`/manhwa/${m.slug}`}><h3>{m.title}</h3></Link><p>{m.author}</p><div className="progress"><span style={{width:`${row.progress}%`}}/></div><small>{digits(row.progress)}٪ پیشرفت</small></div><button className="icon-btn danger" onClick={()=>remove(row.id)}><Trash2/></button></article>})}</div>:<Empty icon={<Library/>} title="این قفسه خالی است" text="از صفحه هر مانهوا، آن را به کتابخانه‌ات اضافه کن."/>}</section></div></PageHero>;
}

function AdminPage(){const {session,user,isOwner,permissions}=useAuth();const token=session?.access_token;const [tab,setTab]=useState('dashboard');const [error,setError]=useState('');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [stats,setStats]=useState<Record<string,number>>({});const [viewStats,setViewStats]=useState<ViewStats>({total:0,items:[]});const [manhwas,setManhwas]=useState<Manhwa[]>([]);const [genres,setGenres]=useState<Genre[]>([]);const [comments,setComments]=useState<Comment[]>([]);const [adminReplies,setAdminReplies]=useState<CommentReply[]>([]);const [adminPins,setAdminPins]=useState<PinnedComment[]>([]);const [adminReplyTo,setAdminReplyTo]=useState<number|null>(null);const [adminReplyBody,setAdminReplyBody]=useState('');const [reports,setReports]=useState<ContactReport[]>([]);const [profiles,setProfiles]=useState<Profile[]>([]);const [admins,setAdmins]=useState<AdminRecord[]>([]);const [userSearch,setUserSearch]=useState('');const [adminEditor,setAdminEditor]=useState<{id:string;email:string;permissions:string[];mode:'promote'|'edit'}|null>(null);const [accountName,setAccountName]=useState(user?.user_metadata?.display_name||user?.email?.split('@')[0]||'');const [accountColor,setAccountColor]=useState('#eab308');const [accountAvatar,setAccountAvatar]=useState(user?.user_metadata?.avatar_url||'');const [accountBusy,setAccountBusy]=useState(false);const [accountMessage,setAccountMessage]=useState('');const accountAvatarInput=useRef<HTMLInputElement>(null);const [content,setContent]=useState<ContentRow[]>([]);const [chapters,setChapters]=useState<Chapter[]>([]);const [credits,setCredits]=useState<ManhwaCredit[]>([]);const [topRows,setTopRows]=useState<TopManhwa[]>([]);const [topChoice,setTopChoice]=useState('');const [writer,setWriter]=useState('');const [editing,setEditing]=useState<Manhwa|null>(null);const [manhwaForm,setManhwaForm]=useState({title:'',english_title:'',author:'',summary:'',cover_url:'',status:'در حال انتشار',rating:'8.5',genre_ids:[] as number[],is_featured:false});const [genreForm,setGenreForm]=useState({name:'',description:'',accent:'#f59e0b'});const [uploadManhwa,setUploadManhwa]=useState('');const [uploadProgress,setUploadProgress]=useState<Record<string,number>>({});const [chapterManhwaId,setChapterManhwaId]=useState<number|null>(null);const [chapterStart,setChapterStart]=useState('1');const filesRef=useRef<HTMLInputElement>(null);
 const [uploadStates,setUploadStates]=useState<Record<string,string>>({});const [pendingUploadFiles,setPendingUploadFiles]=useState<File[]>([]);const [isEnd,setIsEnd]=useState(false);const [coverMode,setCoverMode]=useState<'url'|'upload'>('url');const [coverBusy,setCoverBusy]=useState(false);const [contentSection,setContentSection]=useState<'home'|'about'|'contact'>('home');const coverFileInput=useRef<HTMLInputElement>(null);
 const {data:adminLayout,setData:setAdminLayout,reload:reloadAdminLayout}=useApiData<SiteLayoutRow[]>('/api/site-layout',[]);
 const [analyticsMetric,setAnalyticsMetric]=useState<'site_view'|'manhwa_read'|'manhwa_download'|'manhwa_view'|'manhwa_summary'>('site_view');const [weekOffset,setWeekOffset]=useState(0);const [yearOffset,setYearOffset]=useState(0);const [analyticsLoading,setAnalyticsLoading]=useState(false);const [analytics,setAnalytics]=useState<AnalyticsData|null>(null);const [dashboardSummary,setDashboardSummary]=useState<AnalyticsData|null>(null);
 const load=useCallback(async()=>{if(!token)return;setBusy(true);setError('');try{const [s,m,g,c,ar,r,u,ad,ct,ch,cr,top,views]=await Promise.all([(isOwner||permissions.includes('dashboard'))?api<Record<string,number>>('/api/admin-stats',{},token):Promise.resolve({}),api<Manhwa[]>('/api/manhwas'),api<Genre[]>('/api/genres'),(isOwner||permissions.includes('comments'))?api<Comment[]>('/api/comments?all=true',{},token):Promise.resolve([]),(isOwner||permissions.includes('comments'))?api<CommentReply[]>('/api/replies?all=true',{},token):Promise.resolve([]),(isOwner||permissions.includes('reports'))?api<ContactReport[]>('/api/contact',{},token):Promise.resolve([]),(isOwner||permissions.includes('users'))?api<Profile[]>('/api/users',{},token):Promise.resolve([]),isOwner?api<AdminRecord[]>('/api/admins',{},token):Promise.resolve([]),api<ContentRow[]>('/api/site-content'),api<Chapter[]>('/api/chapters'),api<ManhwaCredit[]>('/api/manhwa-credits'),api<TopManhwa[]>('/api/top-manhwas'),(isOwner||permissions.includes('dashboard'))?api<ViewStats>('/api/views',{},token):Promise.resolve({total:0,items:[]})]);setStats(s);setManhwas(m);setGenres(g);setComments(c);setAdminReplies(ar);setReports(r);setProfiles(u);setAdmins(ad);setContent(ct);setChapters(ch);setCredits(cr);setTopRows(top);setViewStats(views);}catch(e){setError(e instanceof Error?e.message:'خطا')}finally{setBusy(false)}},[token,isOwner,permissions]);useEffect(()=>{load()},[load]);
 const loadAdminPersonal=useCallback(async()=>{if(!token)return;try{const[pref,avatar,pins]=await Promise.all([api<AdminPreference>('/api/admin-preferences',{},token),api<UserAvatar|null>('/api/avatar',{},token),api<PinnedComment[]>('/api/pins')]);setAccountColor(pref.comment_color||'#eab308');if(avatar?.url)setAccountAvatar(avatar.url);setAdminPins(pins);}catch{}},[token]);useEffect(()=>{loadAdminPersonal()},[loadAdminPersonal]);
 useEffect(()=>{if(!token||(!isOwner&&!permissions.includes('dashboard')))return;setAnalytics(null);setAnalyticsLoading(true);api<AnalyticsData>(`/api/analytics?type=${analyticsMetric}&week_offset=${weekOffset}&year_offset=${yearOffset}`,{},token).then(setAnalytics).catch(e=>setError(e instanceof Error?e.message:'خطای آمار')).finally(()=>setAnalyticsLoading(false));},[token,isOwner,permissions,analyticsMetric,weekOffset,yearOffset]);
 useEffect(()=>{if(!token||(!isOwner&&!permissions.includes('dashboard')))return;api<AnalyticsData>('/api/analytics?type=manhwa_summary',{},token).then(setDashboardSummary).catch(()=>{});},[token,isOwner,permissions]);
 const notify=(text:string)=>{setMessage(text);setTimeout(()=>setMessage(''),3500)};
 const saveManhwa=async(e:FormEvent)=>{e.preventDefault();setError('');try{const saved=await api<Manhwa>('/api/manhwas',{method:editing?'PUT':'POST',body:JSON.stringify({...manhwaForm,id:editing?.id,rating:Number(manhwaForm.rating)})},token);await api('/api/manhwa-credits',{method:'POST',body:JSON.stringify({manhwa_id:saved.id,writer})},token);setEditing(null);setWriter('');setManhwaForm({title:'',english_title:'',author:'',summary:'',cover_url:'',status:'در حال انتشار',rating:'8.5',genre_ids:[],is_featured:false});notify('مانهوا با موفقیت ذخیره شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const uploadCover=async(file?:File)=>{if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){setError('کاور باید JPG، PNG یا WEBP و حداکثر ۱۰ مگابایت باشد.');return;}setCoverBusy(true);setError('');try{const signed=await api<{path:string;token:string}>('/api/cover-upload',{method:'POST',body:JSON.stringify({action:'sign',fileSize:file.size,contentType:file.type})},token);const{error:uploadError}=await supabase.storage.from('manhwa-covers').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type});if(uploadError)throw uploadError;const result=await api<{url:string}>('/api/cover-upload',{method:'POST',body:JSON.stringify({action:'finalize',path:signed.path})},token);setManhwaForm({...manhwaForm,cover_url:result.url});notify('کاور آپلود و انتخاب شد.');}catch(e){setError(e instanceof Error?e.message:'آپلود کاور ناموفق بود.')}finally{setCoverBusy(false)}};
 const editManhwa=(m:Manhwa)=>{setEditing(m);setWriter(credits.find(c=>c.manhwa_id===m.id)?.writer||'');setManhwaForm({title:m.title,english_title:m.english_title||'',author:m.author,summary:m.summary,cover_url:m.cover_url,status:m.status,rating:String(m.rating),genre_ids:m.genre_ids||[],is_featured:m.is_featured});window.scrollTo({top:0,behavior:'smooth'})};
 const del=async(resource:string,id:number|string)=>{if(!confirm('از حذف این مورد مطمئن هستید؟'))return;try{await api(`/api/${resource}`,{method:'DELETE',body:JSON.stringify({id})},token);notify('مورد انتخاب‌شده حذف شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const editChapterNumber=async(chapter:Chapter)=>{const value=prompt('شماره جدید چپتر را وارد کنید (مثال: ۲ یا ۲&۳):',chapter.display_number||String(chapter.chapter_number));if(value===null)return;const parsed=parseChapterInput(value);if(!parsed){setError('شماره چپتر معتبر نیست؛ برای چپتر فرعی از فرم ۲&۳ استفاده کنید.');return;}if(chapters.some(item=>item.id!==chapter.id&&item.manhwa_id===chapter.manhwa_id&&Number(item.chapter_number)===parsed.sort)){setError('این شماره چپتر قبلاً برای همین مانهوا ثبت شده است.');return;}try{await api('/api/chapters',{method:'PUT',body:JSON.stringify({id:chapter.id,chapter_number:parsed.sort,display_number:parsed.display,title:`چپتر ${parsed.display}`})},token);notify('شماره چپتر ویرایش شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const addGenre=async(e:FormEvent)=>{e.preventDefault();if(genreForm.name.trim().length<2){setError('نام ژانر معتبر نیست.');return;}try{await api('/api/genres',{method:'POST',body:JSON.stringify(genreForm)},token);setGenreForm({name:'',description:'',accent:'#f59e0b'});notify('ژانر جدید اضافه شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const addTopManhwa=async()=>{if(!topChoice)return;setError('');try{await api('/api/top-manhwas',{method:'POST',body:JSON.stringify({manhwa_id:Number(topChoice)})},token);setTopChoice('');notify('مانهوا به فهرست برتر اضافه شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const removeTopManhwa=async(manhwaId:number)=>{try{await api('/api/top-manhwas',{method:'DELETE',body:JSON.stringify({manhwa_id:manhwaId})},token);notify('مانهوا از فهرست برتر حذف شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const submitAdminReply=async(e:FormEvent,commentId:number)=>{e.preventDefault();if(adminReplyBody.trim().length<2){setError('پاسخ باید حداقل ۲ حرف باشد.');return;}try{await api('/api/replies',{method:'POST',body:JSON.stringify({comment_id:commentId,body:adminReplyBody})},token);setAdminReplyBody('');setAdminReplyTo(null);notify('پاسخ مدیر ثبت شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const saveAdminAccount=async(e:FormEvent)=>{e.preventDefault();if(accountName.trim().length<2){setAccountMessage('نام نمایشی باید حداقل ۲ حرف باشد.');return;}setAccountBusy(true);setAccountMessage('');try{const{error:updateError}=await supabase.auth.updateUser({data:{display_name:accountName.trim()}});if(updateError)throw updateError;await Promise.all([api('/api/users',{method:'POST',body:JSON.stringify({display_name:accountName.trim()})},token),api('/api/admin-preferences',{method:'PUT',body:JSON.stringify({comment_color:accountColor})},token)]);setAccountMessage('تنظیمات حساب ذخیره شد.');}catch(e){setAccountMessage(e instanceof Error?e.message:'ذخیره تنظیمات ناموفق بود.')}finally{setAccountBusy(false)}};
 const uploadAdminAvatar=async(file?:File)=>{if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)||file.size>5*1024*1024){setAccountMessage('فقط تصویر JPG یا PNG تا ۵ مگابایت مجاز است.');return;}setAccountBusy(true);try{const signed=await api<{path:string;token:string}>('/api/avatar',{method:'POST',body:JSON.stringify({action:'sign',fileSize:file.size,contentType:file.type})},token);const{error:uploadError}=await supabase.storage.from('profile-images').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type});if(uploadError)throw uploadError;const saved=await api<UserAvatar>('/api/avatar',{method:'POST',body:JSON.stringify({action:'finalize',path:signed.path,contentType:file.type})},token);setAccountAvatar(saved.url);await supabase.auth.updateUser({data:{avatar_url:saved.url}});setAccountMessage('عکس پروفایل تغییر کرد.');}catch(e){setAccountMessage(e instanceof Error?e.message:'آپلود تصویر ناموفق بود.')}finally{setAccountBusy(false)}};
 const togglePin=async(commentId:number)=>{const pinned=adminPins.some(pin=>pin.comment_id===commentId);try{await api('/api/pins',{method:pinned?'DELETE':'POST',body:JSON.stringify({comment_id:commentId})},token);notify(pinned?'کامنت از سنجاق خارج شد.':'کامنت سنجاق شد.');loadAdminPersonal()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const permissionOptions=[['dashboard','نمای کلی و آمار'],['manhwas','مدیریت مانهواها'],['top','مانهواهای برتر'],['genres','مدیریت ژانرها'],['uploads','آپلود PDF'],['comments','مدیریت کامنت‌ها'],['reports','گزارشات'],['users','کاربران'],['content','متن‌های سایت'],['layout','چیدمان سایت']] as const;
 const saveAdminAccess=async()=>{if(!adminEditor)return;try{await api('/api/admins',{method:adminEditor.mode==='promote'?'POST':'PUT',body:JSON.stringify({user_id:adminEditor.id,permissions:adminEditor.permissions})},token);notify(adminEditor.mode==='promote'?'کاربر ادمین شد.':'دسترسی‌های ادمین بروزرسانی شد.');setAdminEditor(null);load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const removeAdmin=async(id:string)=>{if(!confirm('دسترسی مدیریت این کاربر حذف شود؟'))return;try{await api('/api/admins',{method:'DELETE',body:JSON.stringify({user_id:id})},token);notify('دسترسی ادمین حذف شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const saveContent=async(row:ContentRow)=>{try{await api('/api/site-content',{method:'PUT',body:JSON.stringify(row)},token);notify('متن سایت بروزرسانی شد.');load()}catch(e){setError(e instanceof Error?e.message:'خطا')}};
 const moveLayoutSection=(index:number,direction:-1|1)=>{const target=index+direction;if(target<0||target>=adminLayout.length)return;const next=[...adminLayout],[moved]=next.splice(index,1);next.splice(target,0,moved);setAdminLayout(next.map((row,position)=>({...row,position:position+1})))};
 const saveLayout=async()=>{try{await api('/api/site-layout',{method:'PUT',body:JSON.stringify({ordered_keys:adminLayout.map(row=>row.section_key)})},token);notify('چیدمان صفحه اصلی ذخیره شد.');reloadAdminLayout()}catch(e){setError(e instanceof Error?e.message:'ذخیره چیدمان ناموفق بود.')}};
 const uploadFiles=async(filesInput:FileList|File[]|null)=>{
  const files=filesInput?Array.from(filesInput):[];
  if(!files.length||!uploadManhwa)return setError('ابتدا مانهوا و فایل‌ها را انتخاب کنید.');
  const limit=200*1024*1024,chunkSize=8*1024*1024;
  const invalid=files.find(file=>!file.name.toLowerCase().endsWith('.pdf')||(file.type&&file.type!=='application/pdf')||file.size>limit);
  if(invalid)return setError(!invalid.name.toLowerCase().endsWith('.pdf')||(invalid.type&&invalid.type!=='application/pdf')?`${invalid.name}: فرمت فایل معتبر نیست؛ فقط PDF مجاز است.`:`${invalid.name}: حجم فایل بیشتر از سقف ۲۰۰ مگابایت است.`);
  const parsedStart=parseChapterInput(chapterStart);
  if(!parsedStart)return setError('شماره چپتر معتبر نیست؛ می‌توانید از فرم ۲&۳ برای چپتر فرعی استفاده کنید.');
  setPendingUploadFiles(files);setBusy(true);setError('');setUploadProgress({});setUploadStates({});
  try{
   for(let i=0;i<files.length;i++){
    const file=files[i],progressKey=`${i+1}. ${file.name}`,nextNumber=(parsedStart.right??parsedStart.sort)+i-(parsedStart.right!==null?1:0),chapterSpec=i===0?parsedStart:{display:String(nextNumber),sort:nextNumber,right:null},chapterNumber=chapterSpec.sort,chapterLabel=chapterSpec.display;
    const resumeKey=`manhwa-upload:${uploadManhwa}:${file.name}:${file.size}:${file.lastModified}:${chapterLabel}`;
    let resume:{uploadId:string;paths:(string|null)[]}={uploadId:crypto.randomUUID(),paths:[]};
    try{const stored=localStorage.getItem(resumeKey);if(stored)resume=JSON.parse(stored)}catch{}
    const totalChunks=Math.ceil(file.size/chunkSize);resume.paths=Array.from({length:totalChunks},(_,index)=>resume.paths[index]||null);
    let uploadedBytes=resume.paths.reduce((sum,path,index)=>sum+(path?Math.min(chunkSize,file.size-index*chunkSize):0),0);
    setUploadProgress(prev=>({...prev,[progressKey]:Math.round(uploadedBytes/file.size*100)}));setUploadStates(prev=>({...prev,[progressKey]:uploadedBytes?'در حال ادامه آپلود قبلی...':'در حال آماده‌سازی...'}));
    for(let chunkIndex=0;chunkIndex<totalChunks;chunkIndex++){
     if(resume.paths[chunkIndex])continue;
     const chunk=file.slice(chunkIndex*chunkSize,Math.min(file.size,(chunkIndex+1)*chunkSize),'application/pdf');let uploaded=false,lastError:unknown;
     for(let attempt=1;attempt<=5&&!uploaded;attempt++){
      if(!navigator.onLine)setUploadStates(prev=>({...prev,[progressKey]:'اتصال قطع است؛ در انتظار وصل‌شدن اینترنت...'}));
      await waitForConnection();
      try{
       setUploadStates(prev=>({...prev,[progressKey]:attempt>1?`تلاش مجدد ${digits(attempt)} از ۵...`:`در حال ارسال قطعه ${digits(chunkIndex+1)} از ${digits(totalChunks)}...`}));
       const signed=await api<{path:string;signedUrl:string}>('/api/upload',{method:'POST',body:JSON.stringify({action:'signChunk',fileName:file.name,fileSize:file.size,chunkSize:chunk.size,contentType:'application/pdf',manhwaId:Number(uploadManhwa),chapterNumber,chapterLabel,uploadId:resume.uploadId,chunkIndex})},token);
       await uploadFileWithProgress(signed.signedUrl,chunk,percent=>setUploadProgress(prev=>({...prev,[progressKey]:Math.round((uploadedBytes+chunk.size*percent/100)/file.size*100)})));
       uploaded=true;resume.paths[chunkIndex]=signed.path;uploadedBytes+=chunk.size;localStorage.setItem(resumeKey,JSON.stringify(resume));
      }catch(e){lastError=e;if(attempt<5)await new Promise(resolve=>setTimeout(resolve,Math.min(15000,1500*2**(attempt-1))))}
     }
     if(!uploaded)throw new Error(`${file.name}: پس از ۵ تلاش آپلود نشد. ${lastError instanceof Error?lastError.message:'اتصال را بررسی کنید.'}`);
    }
    setUploadStates(prev=>({...prev,[progressKey]:'در حال ثبت نهایی چپتر...'}));
    await api('/api/upload',{method:'POST',body:JSON.stringify({action:'finalizeChunks',paths:resume.paths,fileName:file.name,fileSize:file.size,manhwaId:Number(uploadManhwa),chapterNumber,chapterLabel,title:`چپتر ${chapterLabel}`,isEnd:isEnd&&i===files.length-1})},token);
    localStorage.removeItem(resumeKey);setUploadProgress(prev=>({...prev,[progressKey]:100}));setUploadStates(prev=>({...prev,[progressKey]:'آپلود کامل شد'}));
   }
   setPendingUploadFiles([]);setIsEnd(false);setChapterManhwaId(Number(uploadManhwa));notify(`${digits(files.length)} فایل با موفقیت بارگذاری شد.`);if(filesRef.current)filesRef.current.value='';load();
  }catch(e){setError(e instanceof Error?e.message:'آپلود ناموفق بود؛ فایل را دوباره انتخاب کنید تا از ادامه قبلی انجام شود.')}finally{setBusy(false)}
 };
 const allNav=[['account','حساب',CircleUserRound],['dashboard','نمای کلی',BarChart3],['manhwas','مانهواها',BookOpen],['top','مانهواهای برتر',Star],['genres','ژانرها',Layers3],['uploads','فایل‌های PDF',FileText],['comments','کامنت‌ها',MessageCircle],['reports','گزارشات',Send],['users','کاربران',Users],['admins','لیست ادمین‌ها',ShieldCheck],['content','متن‌های سایت',Pencil],['layout','چیدمان',Layers3]] as const;
 const nav=allNav.filter(([key])=>key==='account'||(key==='admins'?isOwner:isOwner||permissions.includes(key)));
 useEffect(()=>{if(!isOwner&&tab!=='account'&&!permissions.includes(tab))setTab('account')},[isOwner,permissions,tab]);
 const accessEditor=adminEditor&&<div className="admin-access-editor"><div className="panel-title"><div><h2>{adminEditor.mode==='promote'?'تبدیل کاربر به ادمین':'ویرایش دسترسی ادمین'}</h2><p>{adminEditor.email}</p></div><ShieldCheck/></div><div className="permission-grid">{permissionOptions.map(([key,label])=><label key={key}><input type="checkbox" checked={adminEditor.permissions.includes(key)} onChange={()=>setAdminEditor({...adminEditor,permissions:adminEditor.permissions.includes(key)?adminEditor.permissions.filter(item=>item!==key):[...adminEditor.permissions,key]})}/>{label}</label>)}</div><div className="editor-actions"><button className="primary-btn" onClick={saveAdminAccess}><ShieldCheck/> ذخیره دسترسی‌ها</button><button className="ghost-btn" onClick={()=>setAdminEditor(null)}>انصراف</button></div></div>;
 const metricOptions=[['site_view','تعداد بازدید از سایت'],['manhwa_read','تعداد خواندن مانهوا'],['manhwa_download','تعداد دانلود کردن مانهوا'],['manhwa_view','تعداد بازدید هر مانهوا'],['manhwa_summary','بازدید و دانلود هر مانهوا']] as const;
 const summaryFor=(manhwaId:number)=>dashboardSummary?.by_manhwa.find(item=>item.manhwa_id===manhwaId);
 const showAnalyticsCharts=analyticsMetric!=='manhwa_view'&&analyticsMetric!=='manhwa_summary';
 const analyticsPanel=<section className="analytics-panel"><div className="analytics-tabs">{metricOptions.map(([key,label])=><button className={analyticsMetric===key?'active':''} onClick={()=>setAnalyticsMetric(key)} key={key}>{label}</button>)}</div>{analyticsLoading&&!analytics?<div className="analytics-loading"><LoaderCircle className="spin"/> در حال محاسبه آمار...</div>:analytics&&<>{showAnalyticsCharts&&<><AnalyticsChart title="آمار ساعتی امروز" data={analytics.hourly}/><div className="chart-period-head"><div><button onClick={()=>setWeekOffset(value=>Math.min(52,value+1))}>هفته قبل</button><strong>{analytics.week_label}</strong><button disabled={weekOffset===0} onClick={()=>setWeekOffset(value=>Math.max(0,value-1))}>هفته بعد</button></div><span className={analytics.comparison.week>=0?'positive':'negative'}>{analytics.comparison.week>=0?'افزایش':'کاهش'} {digits(Math.abs(analytics.comparison.week))}٪ نسبت به هفته قبل</span></div><AnalyticsChart title="آمار هفتگی" data={analytics.weekly}/><div className="chart-period-head"><div><button onClick={()=>setYearOffset(value=>Math.min(10,value+1))}>سال قبل</button><strong>{analytics.year_label}</strong><button disabled={yearOffset===0} onClick={()=>setYearOffset(value=>Math.max(0,value-1))}>سال بعد</button></div><span className={analytics.comparison.year>=0?'positive':'negative'}>{analytics.comparison.year>=0?'افزایش':'کاهش'} {digits(Math.abs(analytics.comparison.year))}٪ نسبت به سال قبل</span></div><AnalyticsChart title="آمار ۱۲ ماه سال" data={analytics.monthly}/></>}{(analyticsMetric==='manhwa_view'||analyticsMetric==='manhwa_summary')&&<div className="analytics-manhwa-list"><h3>{analyticsMetric==='manhwa_summary'?'بازدید و دانلود کل هر مانهوا':'بازدید جداگانه مانهواها'}</h3><div className="analytics-manhwa-row">{analytics.by_manhwa.map(item=><div key={item.manhwa_id}><span>{item.title}</span>{analyticsMetric==='manhwa_summary'?<b><i>{digits(item.views||0)} بازدید</i><em>{digits(item.downloads||0)} دانلود</em></b>:<b>{digits(item.value)} بازدید</b>}</div>)}</div></div>}</>}</section>;
 return <div className="admin-shell"><aside className="admin-sidebar"><Logo/><div className="admin-label"><ShieldCheck/> پنل مدیریت</div><nav><Link to="/" className="admin-home"><Home/> خانه</Link>{nav.map(([k,l,I])=><button key={k} className={tab===k?'active':''} onClick={()=>setTab(k)}><I/>{l}</button>)}</nav></aside><main className="admin-main"><header><div><span>پنل مدیریت / {nav.find(n=>n[0]===tab)?.[1]}</span><h1>{nav.find(n=>n[0]===tab)?.[1]}</h1></div><div className="admin-user"><div>م</div><span><strong>{isOwner?'مالک مانهوا هاب':'مدیر مانهوا هاب'}</strong><small>{isOwner?'مادارا · دسترسی مالک':'دسترسی کامل'}</small></span></div></header>{message&&<div className="success-toast">{message}</div>}<ErrorBox message={error}/>{busy&&<div className="thin-loading"><span/></div>}
 {tab==='account'&&<section className="admin-card admin-account-card"><div className="panel-title"><div><h2>حساب مدیریت</h2><p>نام، تصویر و رنگ نمایش پاسخ‌های ادمین</p></div><CircleUserRound/></div><div className="admin-account-layout"><div className="admin-account-avatar">{accountAvatar?<img src={accountAvatar} alt="پروفایل ادمین"/>:<span>{accountName?.[0]||'ا'}</span>}<input ref={accountAvatarInput} hidden type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png" onChange={e=>uploadAdminAvatar(e.target.files?.[0])}/><button onClick={()=>accountAvatarInput.current?.click()} disabled={accountBusy}><UploadCloud/> تغییر عکس پروفایل</button></div><form onSubmit={saveAdminAccount}><label>نام نمایش در کامنت‌ها<input value={accountName} onChange={e=>setAccountName(e.target.value)} maxLength={40}/></label><label>رنگ نمایش ادمین<div className="admin-color-picker"><input type="color" value={accountColor} onChange={e=>setAccountColor(e.target.value)}/><span style={{borderColor:accountColor,background:`color-mix(in srgb, ${accountColor} 18%, white)`,color:accountColor}}>{accountName||'ادمین'}</span></div></label><button className="primary-btn" disabled={accountBusy}><ShieldCheck/> ذخیره تنظیمات</button>{accountMessage&&<p>{accountMessage}</p>}</form></div></section>}
 {tab==='dashboard'&&<>{analyticsPanel}<div className="stats-grid"><Stat icon={<Users/>} label="کاربران" value={stats.users}/><Stat icon={<BookOpen/>} label="مانهواها" value={stats.manhwas}/><Stat icon={<Layers3/>} label="ژانرها" value={stats.genres}/><Stat icon={<MessageCircle/>} label="دیدگاه‌ها" value={stats.comments}/><Stat icon={<Eye/>} label="خواندن کل" value={viewStats.total}/></div><div className="admin-grid"><section className="admin-card dashboard-manhwas-card"><div className="panel-title"><h2>مدیریت مانهواها</h2><button onClick={()=>setTab('manhwas')}>همه مانهواها</button></div><div className="dashboard-horizontal-list">{manhwas.slice(0,8).map(m=>{const summary=summaryFor(m.id);return <div className="admin-list-row dashboard-manhwa-row" key={m.id}><img src={m.cover_url}/><div><strong>{m.title}</strong><small dir="ltr">{m.english_title}</small></div><div className="dashboard-card-stats"><span><Eye/> {digits(summary?.views||0)}</span><span><Download/> {digits(summary?.downloads||0)}</span></div><button onClick={()=>{setTab('manhwas');editManhwa(m)}}><Pencil/> مدیریت</button></div>})}</div></section><section className="admin-card"><div className="panel-title"><h2>دیدگاه‌های اخیر</h2><button onClick={()=>setTab('comments')}>مشاهده همه</button></div>{comments.slice(0,5).map(c=><div className="comment-mini" key={c.id}><div>{c.display_name?.[0]}</div><p><strong>{c.display_name}</strong><span>{c.body}</span></p></div>)}</section></div><section className="admin-card table-card wide dashboard-views-card" style={{marginTop:18}}><div className="panel-title"><div><h2>بازدید و دانلود کل مانهواها</h2><p>آمار تکی هر مانهوا به‌صورت افقی</p></div><span>{digits(dashboardSummary?.by_manhwa.reduce((sum,item)=>sum+(item.views||0),0)||0)} بازدید کل</span></div><div className="data-table">{(dashboardSummary?.by_manhwa||[]).map(row=>{const m=manhwas.find(item=>item.id===row.manhwa_id);if(!m)return null;return <div className="data-row dashboard-manhwa-row" key={row.manhwa_id}><img src={m.cover_url}/><div><strong>{m.title}</strong><small dir="ltr">{m.english_title}</small></div><div className="dashboard-card-stats"><span><Eye/> {digits(row.views||0)} بازدید</span><span><Download/> {digits(row.downloads||0)} دانلود</span></div><button onClick={()=>{setTab('manhwas');editManhwa(m)}}><Pencil/> مدیریت</button></div>})}</div></section></>}
 {tab==='manhwas'&&<div className="admin-grid form-grid"><form className="admin-card admin-form" onSubmit={saveManhwa}><div className="panel-title"><h2>{editing?'ویرایش مانهوا':'افزودن مانهوا'}</h2>{editing&&<button type="button" onClick={()=>setEditing(null)}><X/></button>}</div><label>نام فارسی<input required value={manhwaForm.title} onChange={e=>setManhwaForm({...manhwaForm,title:e.target.value})}/></label><label>نام انگلیسی<input required dir="ltr" value={manhwaForm.english_title} onChange={e=>setManhwaForm({...manhwaForm,english_title:e.target.value})}/></label><label>مترجمان<input required value={manhwaForm.author} onChange={e=>setManhwaForm({...manhwaForm,author:e.target.value})}/></label><label>نویسنده<input required value={writer} onChange={e=>setWriter(e.target.value)}/></label><label>خلاصه<textarea required value={manhwaForm.summary} onChange={e=>setManhwaForm({...manhwaForm,summary:e.target.value})}/></label><div className="cover-source"><strong>روش انتخاب کاور</strong><div className="cover-source-toggle"><button type="button" className={coverMode==='url'?'active':''} onClick={()=>setCoverMode('url')}>لینک مستقیم</button><button type="button" className={coverMode==='upload'?'active':''} onClick={()=>setCoverMode('upload')}>آپلود از دستگاه</button></div>{coverMode==='url'?<label>آدرس تصویر کاور<input required type="url" value={manhwaForm.cover_url} onChange={e=>setManhwaForm({...manhwaForm,cover_url:e.target.value})}/></label>:<div className="cover-upload-box">{manhwaForm.cover_url&&<img src={manhwaForm.cover_url} alt="پیش‌نمایش کاور"/>}<input ref={coverFileInput} hidden type="file" accept="image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp" onChange={e=>uploadCover(e.target.files?.[0])}/><button type="button" onClick={()=>coverFileInput.current?.click()} disabled={coverBusy}><UploadCloud/> {coverBusy?'در حال آپلود...':'انتخاب و آپلود کاور'}</button><small>JPG، PNG یا WEBP تا ۱۰ مگابایت</small></div>}</div><div className="two-col"><label>وضعیت<select value={manhwaForm.status} onChange={e=>setManhwaForm({...manhwaForm,status:e.target.value})}><option>در حال انتشار</option><option>پایان‌یافته</option><option>متوقف‌شده</option></select></label><label>امتیاز<input type="number" min="0" max="10" step="0.1" value={manhwaForm.rating} onChange={e=>setManhwaForm({...manhwaForm,rating:e.target.value})}/></label></div><fieldset><legend>ژانرها</legend><div className="checks">{genres.map(g=><label key={g.id}><input type="checkbox" checked={manhwaForm.genre_ids.includes(g.id)} onChange={()=>setManhwaForm({...manhwaForm,genre_ids:manhwaForm.genre_ids.includes(g.id)?manhwaForm.genre_ids.filter(x=>x!==g.id):[...manhwaForm.genre_ids,g.id]})}/>{g.name}</label>)}</div></fieldset><button className="primary-btn"><Plus/> {editing?'ذخیره تغییرات':'افزودن مانهوا'}</button></form><section className="admin-card table-card"><div className="panel-title"><h2>فهرست مانهواها</h2><span>{digits(manhwas.length)} عنوان</span></div><div className="data-table">{manhwas.map(m=><div className="data-row" key={m.id}><img src={m.cover_url}/><div><strong>{m.title}</strong><small dir="ltr">{m.english_title}</small></div><span>{m.status}</span><button onClick={()=>editManhwa(m)}><Pencil/></button><button className="danger" onClick={()=>del('manhwas',m.id)}><Trash2/></button></div>)}</div></section></div>}
 {tab==='genres'&&<div className="admin-grid form-grid"><form className="admin-card admin-form" onSubmit={addGenre}><div className="panel-title"><h2>ژانر جدید</h2><Layers3/></div><label>نام ژانر<input required value={genreForm.name} onChange={e=>setGenreForm({...genreForm,name:e.target.value})}/></label><label>توضیح کوتاه<textarea required maxLength={180} value={genreForm.description} onChange={e=>setGenreForm({...genreForm,description:e.target.value})}/></label><label>رنگ شاخص<input type="color" value={genreForm.accent} onChange={e=>setGenreForm({...genreForm,accent:e.target.value})}/></label><button className="primary-btn"><Plus/> افزودن ژانر</button></form><section className="admin-card table-card"><div className="panel-title"><h2>ژانرها</h2><span>{digits(genres.length)} مورد</span></div>{genres.map(g=><div className="data-row" key={g.id}><i style={{background:g.accent}}/><div><strong>{g.name}</strong><small>{g.description}</small></div><button className="danger" onClick={()=>del('genres',g.id)}><Trash2/></button></div>)}</section></div>}
 {tab==='uploads'&&<div className="admin-grid form-grid"><section className="admin-card upload-card"><UploadCloud/><h2>آپلود پایدار PDF</h2><p>آپلود تکه‌تکه ۸ مگابایتی با ادامه خودکار، زمان انتظار بلند و ۵ بار تلاش مجدد؛ سقف هر فایل ۲۰۰ مگابایت است.</p><label>انتخاب مانهوا<select value={uploadManhwa} onChange={e=>setUploadManhwa(e.target.value)} disabled={busy}><option value="">انتخاب کنید</option>{manhwas.map(m=><option value={m.id} key={m.id}>{m.title}</option>)}</select></label><label>شماره شروع چپتر<input type="text" inputMode="text" placeholder="مثلاً ۲ یا ۲&۳" value={chapterStart} onChange={e=>setChapterStart(e.target.value)} disabled={busy}/></label><label className="end-chapter-toggle"><input type="checkbox" checked={isEnd} onChange={e=>setIsEnd(e.target.checked)} disabled={busy}/><span><b>END</b><small>آخرین فایل انتخاب‌شده، چپتر پایانی مانهوا است</small></span></label><label className={busy?'drop-zone uploading':'drop-zone'}><UploadCloud/><strong>{busy?'آپلود در حال انجام است...':'انتخاب فایل‌های PDF'}</strong><small>{busy?'صفحه را باز نگه دارید؛ در صورت قطع اینترنت آپلود ادامه پیدا می‌کند.':'امکان انتخاب چند فایل همزمان'}</small><input ref={filesRef} type="file" accept="application/pdf,.pdf" multiple disabled={busy} onChange={e=>uploadFiles(e.target.files)}/></label>{Object.entries(uploadProgress).length>0&&<div className="upload-progress-list">{Object.entries(uploadProgress).map(([name,percent])=><div key={name}><span><strong>{name}</strong><b>{digits(percent)}٪</b></span><div className="upload-progress-track"><i style={{width:`${percent}%`}}/></div><small className="upload-state">{uploadStates[name]}</small></div>)}{!busy&&pendingUploadFiles.length>0&&<button className="retry-upload-btn" onClick={()=>uploadFiles(pendingUploadFiles)}><UploadCloud/> ادامه / تلاش مجدد آپلود</button>}</div>}</section><section className="admin-card table-card chapter-library"><div className="panel-title"><div><h2>{chapterManhwaId?'چپترهای مانهوا':'مانهواهای دارای چپتر'}</h2><p>{chapterManhwaId?manhwas.find(m=>m.id===chapterManhwaId)?.title:'برای مشاهده چپترها یک مانهوا را انتخاب کنید'}</p></div>{chapterManhwaId?<button onClick={()=>setChapterManhwaId(null)}><ArrowLeft/> بازگشت</button>:<span>{digits(manhwas.length)} مانهوا</span>}</div>{chapterManhwaId?chapters.filter(ch=>ch.manhwa_id===chapterManhwaId).sort((a,b)=>a.chapter_number-b.chapter_number).map(ch=><div className="data-row" key={ch.id}><FileText/><div><strong>{(ch.file_name||ch.title).replace(/فصل/g,'چپتر')}</strong><small>چپتر {ch.display_number||digits(ch.chapter_number)} {ch.is_final&&<b className="end-badge">END</b>} · {fileSize(ch.file_size)}</small></div><button aria-label="ویرایش شماره چپتر" onClick={()=>editChapterNumber(ch)}><Pencil/></button><Link to={`/reader/${ch.id}`} aria-label="مطالعه PDF"><Eye/></Link><button className="danger" onClick={()=>del('chapters',ch.id)}><Trash2/></button></div>):manhwas.map(m=><button className="manhwa-folder-row" key={m.id} onClick={()=>setChapterManhwaId(m.id)}><img src={m.cover_url} alt=""/><span><strong>{m.title}</strong><small>{digits(chapters.filter(ch=>ch.manhwa_id===m.id).length)} چپتر آپلودشده</small></span><ChevronLeft/></button>)}</section></div>}
 {tab==='comments'&&<section className="admin-card table-card wide"><div className="panel-title"><h2>مدیریت کامنت‌ها و پاسخ‌ها</h2><span>{digits(comments.length)} دیدگاه</span></div>{[...comments].sort((a,b)=>Number(adminPins.some(pin=>pin.comment_id===b.id))-Number(adminPins.some(pin=>pin.comment_id===a.id))).map(c=>{const thread=adminReplies.filter(reply=>reply.comment_id===c.id);const hasReplied=thread.some(reply=>reply.user_id===user?.id),isPinned=adminPins.some(pin=>pin.comment_id===c.id);return <div className={isPinned?'admin-comment-block pinned':'admin-comment-block'} key={c.id}><div className="moderation-row"><div className="avatar">{c.display_name?.[0]}</div><div><strong>{c.display_name}</strong><small>{dateFa(c.created_at)}</small><p>{c.body}</p></div><span>{c.status}</span><button className={isPinned?'pin-admin-btn active':'pin-admin-btn'} onClick={()=>togglePin(c.id)}><Bookmark fill={isPinned?'currentColor':'none'}/> {isPinned?'برداشتن سنجاق':'سنجاق'}</button><button className="admin-reply-btn" disabled={hasReplied||thread.length>=200} onClick={()=>{setAdminReplyTo(adminReplyTo===c.id?null:c.id);setAdminReplyBody('')}}><MessageCircle/> {hasReplied?'پاسخ داده‌اید':'پاسخ'}</button><button className="danger" onClick={()=>del('comments',c.id)}><Trash2/></button></div>{thread.length>0&&<div className="admin-replies-list">{thread.map(reply=><div key={reply.id}><ReplyName reply={reply}/><span>{reply.body}</span></div>)}</div>}{adminReplyTo===c.id&&!hasReplied&&thread.length<200&&<form className="admin-reply-form" onSubmit={e=>submitAdminReply(e,c.id)}><textarea autoFocus value={adminReplyBody} onChange={e=>setAdminReplyBody(e.target.value)} placeholder={`پاسخ مدیر به ${c.display_name}...`} maxLength={700}/><button className="primary-btn"><Send/> ارسال پاسخ</button><button type="button" className="ghost-btn" onClick={()=>setAdminReplyTo(null)}>انصراف</button></form>}<small className="reply-capacity">{digits(thread.length)} از ۲۰۰ پاسخ</small></div>})}</section>}
 {tab==='reports'&&<section className="admin-card reports-card wide"><div className="panel-title"><div><h2>گزارشات کاربران</h2><p>گزارش‌های ارسال‌شده از صفحه تماس با ما</p></div><span>{digits(reports.length)} گزارش</span></div>{reports.length?reports.map(report=><article className={report.status==='new'?'report-row unread':'report-row'} key={report.id}><div className="report-head"><div className="avatar">{report.avatar_url?<img src={report.avatar_url} alt={`پروفایل ${report.name}`}/>:report.name?.[0]||'گ'}</div><div><strong>{report.subject}</strong><small>{report.name} · {dateFa(report.created_at)}</small></div><span>{report.status==='new'?'جدید':'بررسی‌شده'}</span></div><p>{report.message}</p><div className="report-actions">{report.status==='new'&&<button onClick={async()=>{await api('/api/contact',{method:'PUT',body:JSON.stringify({id:report.id,status:'reviewed'})},token);load()}}><Eye/> علامت‌گذاری به‌عنوان بررسی‌شده</button>}<button className="danger" onClick={()=>del('contact',report.id)}><Trash2/> حذف گزارش</button></div></article>):<Empty icon={<Send/>} title="گزارشی وجود ندارد" text="گزارش‌های کاربران پس از ارسال در این بخش نمایش داده می‌شوند."/>}</section>}
 {tab==='users'&&<section className="admin-card table-card wide"><div className="panel-title"><h2>مدیریت کاربران</h2><span>{digits(profiles.length)} کاربر</span></div><label className="admin-user-search"><Search/><input type="email" value={userSearch} onChange={e=>setUserSearch(e.target.value)} placeholder="جستجوی ایمیل کاربر..."/></label>{isOwner&&accessEditor}{profiles.filter(p=>p.email.toLowerCase().includes(userSearch.trim().toLowerCase())).map(p=><div className="user-row" key={p.id}><div className="avatar">{p.display_name?.[0]||p.email[0]}</div><div><strong>{p.display_name||'کاربر'}</strong><small>{p.email}</small></div><span className={`status-dot ${p.status}`}>{p.status==='active'?'فعال':'تعلیق'}</span><small>{dateFa(p.created_at)}</small><button onClick={async()=>{await api('/api/users',{method:'PUT',body:JSON.stringify({id:p.id,status:p.status==='active'?'suspended':'active'})},token);load()}}>{p.status==='active'?'تعلیق':'فعال‌سازی'}</button>{isOwner&&p.role==='user'&&<button className="promote-admin-btn" onClick={()=>setAdminEditor({id:p.id,email:p.email,permissions:['dashboard'],mode:'promote'})}><ShieldCheck/> ادمین کردن</button>}</div>)}</section>}
 {tab==='admins'&&isOwner&&<section className="admin-card admin-list-card wide"><div className="panel-title"><div><h2>لیست ادمین‌ها</h2><p>مرتب‌شده از قدیمی‌ترین تا جدیدترین</p></div><span>{digits(admins.length)} ادمین</span></div>{accessEditor}<div className="admin-records">{admins.map(admin=><article key={admin.id}><div className="avatar">{admin.display_name?.[0]||admin.email[0]}</div><div><strong>{admin.display_name}</strong><small>{admin.email}</small><em>عضویت: {dateFa(admin.granted_at)}</em></div><div className="permission-tags">{admin.permissions.map(permission=><span key={permission}>{permissionOptions.find(item=>item[0]===permission)?.[1]||permission}</span>)}</div>{admin.role==='owner'?<b className="owner-badge">مالک</b>:<div className="admin-record-actions"><button onClick={()=>setAdminEditor({id:admin.id,email:admin.email,permissions:admin.permissions,mode:'edit'})}><Pencil/> ویرایش دسترسی</button><button className="danger" onClick={()=>removeAdmin(admin.id)}><Trash2/> حذف ادمین</button></div>}</article>)}</div></section>}
 {tab==='content'&&<section className="admin-card content-editor wide"><div className="panel-title"><div><h2>متن‌های قابل ویرایش سایت</h2><p>فقط نوشتار بخش انتخاب‌شده را تغییر دهید؛ نام «مانهوا هاب» ثابت است.</p></div><Settings2/></div><div className="content-page-tabs"><button className={contentSection==='home'?'active':''} onClick={()=>setContentSection('home')}><Home/> خانه</button><button className={contentSection==='about'?'active':''} onClick={()=>setContentSection('about')}><Sparkles/> درباره ما</button><button className={contentSection==='contact'?'active':''} onClick={()=>setContentSection('contact')}><MessageCircle/> تماس</button></div><div className="content-grid">{content.filter(row=>contentSection==='about'?row.content_key.startsWith('about_'):contentSection==='contact'?row.content_key.startsWith('contact_'):!row.content_key.startsWith('about_')&&!row.content_key.startsWith('contact_')).map(row=><label key={row.id}>{row.label}<textarea value={row.value} onChange={e=>setContent(content.map(x=>x.id===row.id?{...x,value:e.target.value}:x))}/><button className="ghost-btn" onClick={()=>saveContent(row)}><Pencil/> ذخیره نوشتار</button></label>)}</div></section>}
 {tab==='top'&&<section className="admin-card table-card wide"><div className="panel-title"><div><h2>مانهواهای برتر</h2><p>مانهواهای دست‌چین‌شده صفحه اصلی را تعیین کنید؛ سقف انتخاب ۱۵ عنوان است.</p></div><span>{digits(topRows.length)} از ۱۵</span></div><div className="filter-bar" style={{gridTemplateColumns:'1fr auto'}}><label><Star/><select value={topChoice} onChange={e=>setTopChoice(e.target.value)} disabled={topRows.length>=15}><option value="">انتخاب مانهوا</option>{manhwas.filter(m=>!topRows.some(row=>row.manhwa_id===m.id)).map(m=><option value={m.id} key={m.id}>{m.title}</option>)}</select></label><button className="primary-btn" onClick={addTopManhwa} disabled={!topChoice||topRows.length>=15}><Plus/> افزودن به برترها</button></div>{topRows.length>=15&&<div className="error-box">ظرفیت ۱۵ عنوان تکمیل است؛ برای افزودن مانهوا جدید ابتدا یکی از موارد قبلی را حذف کنید.</div>}<div className="data-table">{topRows.map(row=>{const m=manhwas.find(item=>item.id===row.manhwa_id);if(!m)return null;return <div className="data-row" key={row.id}><img src={m.cover_url}/><div><strong>{m.title}</strong><small>{m.author}</small></div><span>دست‌چین‌شده</span><button className="danger" onClick={()=>removeTopManhwa(m.id)}><Trash2/></button></div>})}</div></section>}
 {tab==='layout'&&<section className="admin-card layout-editor wide"><div className="panel-title"><div><h2>چیدمان صفحه اصلی</h2><p>ترتیب نمایش بخش‌ها را تغییر دهید؛ این ساختار برای بخش‌های آینده نیز قابل گسترش است.</p></div><Layers3/></div><div className="layout-list">{adminLayout.map((row,index)=><article key={row.section_key}><span>{digits(index+1)}</span><div><strong>{row.label}</strong><small>{row.section_key}</small></div><button disabled={index===0} onClick={()=>moveLayoutSection(index,-1)}>↑ بالا</button><button disabled={index===adminLayout.length-1} onClick={()=>moveLayoutSection(index,1)}>↓ پایین</button></article>)}</div><button className="primary-btn save-layout-btn" onClick={saveLayout}><ShieldCheck/> ذخیره چیدمان</button></section>}
 </main></div>;
}

function Stat({icon,label,value=0}:{icon:ReactNode;label:string;value?:number}){return <div className="stat-card"><span>{icon}</span><div><small>{label}</small><strong>{digits(value)}</strong><em>آمار زنده</em></div></div>}
function PageHero({eyebrow,title,text,icon,children}:{eyebrow:string;title:string;text:string;icon:ReactNode;children:ReactNode}){return <><section className="page-hero"><div className="container"><span className="eyebrow">{icon}{eyebrow}</span><h1>{title}</h1><p>{text}</p></div></section><section className="container page-content">{children}</section></>}
function Empty({icon,title,text}:{icon:ReactNode;title:string;text:string}){return <div className="empty-state"><span>{icon}</span><h3>{title}</h3><p>{text}</p></div>}
function AboutPage(){const {data}=useApiData<ContentRow[]>('/api/site-content',[]);const c=Object.fromEntries(data.map(x=>[x.content_key,x.value]));return <PageHero eyebrow="پشت داستان ما" title={c.about_title||'درباره مانهوا هاب'} text={c.about_intro||'خانه‌ای برای دوست‌داران داستان‌های تصویری آسیایی.'} icon={<Sparkles/>}><div className="story-grid"><article><span>داستان ما</span><h2>{c.about_heading||'برای خواندن بهتر، کنار هم'}</h2><p>{c.about_body||'مانهوا هاب با هدف ساخت تجربه‌ای سریع، زیبا و منظم برای خوانندگان فارسی‌زبان شکل گرفت. ما باور داریم کشف یک داستان خوب باید ساده و لذت‌بخش باشد.'}</p></article><div className="values"><div><Zap/><h3>سریع و روان</h3><p>طراحی‌شده برای مطالعه بی‌وقفه در هر دستگاه.</p></div><div><ShieldCheck/><h3>امن و قابل اعتماد</h3><p>حریم خصوصی و امنیت حساب‌ها در اولویت ماست.</p></div><div><Heart/><h3>ساخته‌شده با علاقه</h3><p>توسط دوست‌داران مانهوا، برای دوست‌داران مانهوا.</p></div></div></div></PageHero>}
function ContactPage(){
  const{user,session}=useAuth();
  const{data:contactContent}=useApiData<ContentRow[]>('/api/site-content',[]);
  const contactText=Object.fromEntries(contactContent.map(item=>[item.content_key,item.value]));
  const[form,setForm]=useState({subject:'',message:''});
  const[reports,setReports]=useState<ContactReport[]>([]);
  const[status,setStatus]=useState('');
  const[reportsLoading,setReportsLoading]=useState(false);
  const[editingId,setEditingId]=useState<number|null>(null);
  const[editForm,setEditForm]=useState({subject:'',message:''});
  const[now,setNow]=useState(Date.now());
  const loadReports=useCallback(async()=>{if(!session?.access_token)return;setReportsLoading(true);try{setReports(await api<ContactReport[]>('/api/contact',{},session.access_token));}catch(e){setStatus(e instanceof Error?e.message:'خطا در دریافت گزارش‌ها');}finally{setReportsLoading(false)}},[session?.access_token]);
  useEffect(()=>{loadReports()},[loadReports]);
  useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),30000);return()=>clearInterval(id)},[]);
  const submittedToday=reports.some(report=>tehranDay(report.created_at)===tehranDay(now));
  const editable=(report:ContactReport)=>now-new Date(report.created_at).getTime()<=10*60*1000;
  const submit=async(e:FormEvent)=>{e.preventDefault();setStatus('در حال ارسال...');try{await api('/api/contact',{method:'POST',body:JSON.stringify(form)},session?.access_token);setForm({subject:'',message:''});setStatus('گزارش شما با موفقیت ارسال شد.');loadReports()}catch(err){setStatus(err instanceof Error?err.message:'خطا')}};
  const saveEdit=async(e:FormEvent)=>{e.preventDefault();if(!editingId)return;setStatus('در حال ذخیره...');try{await api('/api/contact',{method:'PUT',body:JSON.stringify({id:editingId,...editForm})},session?.access_token);setEditingId(null);setStatus('گزارش ویرایش شد.');loadReports()}catch(err){setStatus(err instanceof Error?err.message:'خطا')}};
  const removeReport=async(id:number)=>{if(!confirm('این گزارش حذف شود؟'))return;try{await api('/api/contact',{method:'DELETE',body:JSON.stringify({id})},session?.access_token);setStatus('گزارش حذف شد.');loadReports()}catch(err){setStatus(err instanceof Error?err.message:'خطا')}};
  const profileName=user?.user_metadata?.display_name||user?.user_metadata?.full_name||user?.email;
  const profileAvatar=user?.user_metadata?.avatar_url;
  return <PageHero eyebrow="ما پاسخگو هستیم" title={contactText.contact_title||'تماس با ما'} text={contactText.contact_subtitle||'پیشنهاد، گزارش یا سوالی داری؟ برامون بنویس.'} icon={<MessageCircle/>}><div className="contact-grid"><div><h2>{contactText.contact_heading||'گفت‌وگو را شروع کنیم'}</h2><p>{contactText.contact_description||'هر حساب در هر روز یک گزارش می‌تواند ارسال کند؛ سهمیه رأس ساعت ۰۰:۰۰ به وقت ایران فعال می‌شود.'}</p>{user&&<div className="report-profile"><div className="avatar">{profileAvatar?<img src={profileAvatar} alt=""/>:profileName?.[0]||'ک'}</div><span><strong>{profileName}</strong><small>{user.email}</small></span></div>}<div className="contact-item"><Clock3/><span><strong>مهلت ویرایش و حذف</strong><small>تا ۱۰ دقیقه پس از ارسال</small></span></div><div className="contact-item"><MessageCircle/><span><strong>{contactText.contact_response_title||'مهلت پاسخ گویی'}</strong><small>{contactText.contact_response_text||'حداکثر تا ۶ ساعت پس از ارسال پیام'}</small></span></div></div>{user?<div className="contact-workspace"><form className="contact-form" onSubmit={submit}><fieldset disabled={submittedToday}><label>موضوع گزارش<input required value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})}/></label><label>متن گزارش<textarea required minLength={10} value={form.message} onChange={e=>setForm({...form,message:e.target.value})}/></label><button className="primary-btn"><Send/> ارسال گزارش</button></fieldset>{submittedToday&&<p className="daily-limit"><Clock3/> سهمیه امروز استفاده شده؛ گزارش بعدی ساعت ۰۰:۰۰ قابل ارسال است.</p>}{status&&<p className="inline-message">{status}</p>}</form><section className="user-reports"><div className="panel-title"><h2>گزارش‌های من</h2><span>{digits(reports.length)} گزارش</span></div>{reportsLoading?<div className="page-loading"><LoaderCircle className="spin"/></div>:reports.length?reports.map(report=><article key={report.id}><header><div><strong>{report.subject}</strong><small>{dateFa(report.created_at)}</small></div><span className={report.status==='reviewed'?'reviewed':'pending'}>{report.status==='reviewed'?'بررسی‌شده':'در انتظار بررسی'}</span></header>{editingId===report.id?<form className="report-edit-form" onSubmit={saveEdit}><input value={editForm.subject} onChange={e=>setEditForm({...editForm,subject:e.target.value})}/><textarea value={editForm.message} onChange={e=>setEditForm({...editForm,message:e.target.value})}/><button className="primary-btn">ذخیره</button><button type="button" className="ghost-btn" onClick={()=>setEditingId(null)}>انصراف</button></form>:<p>{report.message}</p>}{editable(report)&&editingId!==report.id&&<div className="user-report-actions"><button onClick={()=>{setEditingId(report.id);setEditForm({subject:report.subject,message:report.message})}}><Pencil/> ویرایش</button><button className="danger" onClick={()=>removeReport(report.id)}><Trash2/> حذف</button><small>تا {digits(Math.max(0,Math.ceil((10*60*1000-(now-new Date(report.created_at).getTime()))/60000)))} دقیقه دیگر</small></div>}</article>):<Empty icon={<Send/>} title="هنوز گزارشی ندارید" text="گزارش‌های ارسال‌شده اینجا نمایش داده می‌شوند."/>}</section></div>:<div className="contact-form login-note"><LockKeyhole/><span>برای ارسال و مشاهده گزارش‌ها باید ابتدا وارد حساب کاربری شوید.</span><Link to="/login">ورود / ثبت‌نام</Link></div>}</div></PageHero>}
function NotFound(){return <div className="not-found"><span>۴۰۴</span><h1>این صفحه پیدا نشد</h1><p>شاید داستان به چپتر دیگری منتقل شده باشد.</p><Link className="primary-btn" to="/">بازگشت به خانه</Link></div>}
function AdminAwareProfile(){const {isAdmin}=useAuth();return isAdmin?<Navigate to="/admin" replace/>:<ProfilePage/>}

function SiteRoutes(){return <Routes><Route element={<Layout><HomePage/></Layout>} path="/"/><Route element={<Layout><GenresPage/></Layout>} path="/genres"/><Route element={<Layout><GenreDetailPage/></Layout>} path="/genres/:slug"/><Route element={<Layout><ManhwasPage/></Layout>} path="/manhwas"/><Route element={<Layout><ManhwasPage latest/></Layout>} path="/latest"/><Route element={<Layout><ManhwaDetailPage/></Layout>} path="/manhwa/:slug"/><Route element={<ReaderPage/>} path="/reader/:id"/><Route element={<LoginPage/>} path="/login"/><Route element={<LoginPage admin/>} path="/admin-login"/><Route element={<Layout><Protected><AdminAwareProfile/></Protected></Layout>} path="/profile"/><Route element={<Protected admin><AdminPage/></Protected>} path="/admin"/><Route element={<Layout><AboutPage/></Layout>} path="/about"/><Route element={<Layout><ContactPage/></Layout>} path="/contact"/><Route element={<Layout><NotFound/></Layout>} path="*"/></Routes>}
export default function App(){return <AuthProvider><HashRouter><SiteRoutes/></HashRouter></AuthProvider>}
